-- London
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$London$t$, $t$london$t$, $t$Vereinigtes Königreich (Großbritannien)$t$, $t$England$t$, $t$Europa$t$, $t$/images/destinations/london-hero.jpg$t$, $t$Pulsierende Weltmetropole an der Themse mit Big Ben, dem Tower, Buckingham Palace, weltberühmten Museen, West-End-Musicals und royalem Flair.$t$, $t$London ist eine der aufregendsten Metropolen der Welt und vereint jahrhundertealte Geschichte mit pulsierender Moderne. An der Themse reihen sich die ikonischen Wahrzeichen aneinander: der Glockenturm Big Ben mit den Houses of Parliament, die Westminster Abbey, das Riesenrad London Eye und der historische Tower of London mit den Kronjuwelen, direkt neben der prächtigen Tower Bridge. Am Buckingham Palace erlebt man die traditionelle Wachablösung, während sich rund um St Paul's Cathedral und die City das Finanzherz der Stadt erstreckt. London ist zudem ein Paradies für Kulturfans: Weltklasse-Museen wie das British Museum, die National Gallery und die Tate Modern sind kostenlos zugänglich. Im West End locken die besten Musicals und Theater der Welt, in Vierteln wie Soho, Covent Garden, Camden und Notting Hill pulsiert das Leben, und Märkte wie der Borough Market verwöhnen Feinschmecker. Mit seinem multikulturellen Flair, exzellentem Nahverkehr und royaler Eleganz ist London das ideale Ziel für einen Städtetrip – von Deutschland aus in nur kurzer Flugzeit erreichbar.$t$, $t$London ist eine pulsierende Weltmetropole an der Themse mit Wahrzeichen wie Big Ben, dem Tower of London, Buckingham Palace und dem London Eye, weltberühmten kostenlosen Museen und den besten Musicals im West End. Die Stadt eignet sich ideal für einen Städtetrip; für die Einreise sind ein Reisepass und eine kostenpflichtige ETA-Genehmigung nötig.$t$, $t$Mai bis September mit mildem Wetter und langen Tagen ist ideal; der Dezember ist mit weihnachtlicher Beleuchtung besonders festlich. Regen ist in London zu jeder Jahreszeit möglich.$t$, $t$3 bis 5 Tage$t$, ARRAY[$t$Städtereise$t$,$t$Kulturreise$t$,$t$Shopping$t$,$t$Familien$t$,$t$Kulinarik$t$,$t$Wochenendtrip$t$]::text[], $j${"currency":"Britisches Pfund (GBP); nicht Euro","language":"Englisch","flightTime":"ca. 1,5 Stunden ab Deutschland (London); alternativ mit dem Eurostar über Brüssel oder Paris","timezone":"GMT (UTC+0; im Sommer BST, UTC+1), eine Stunde hinter MEZ","visa":"Kein Visum für Touristen (bis 6 Monate), aber ein Reisepass und eine vorab beantragte, kostenpflichtige ETA (elektronische Einreisegenehmigung, rund 16 £) sind erforderlich","bestMonths":"Mai bis September"}$j$::jsonb, $j$["Big Ben und die Houses of Parliament an der Themse","Tower of London und Tower Bridge – Kronjuwelen und historische Festung","Buckingham Palace – royale Residenz mit Wachablösung","London Eye – Riesenrad mit weitem Blick über die Stadt","British Museum und National Gallery – Weltklasse-Museen, kostenlos","West End – die besten Musicals und Theater der Welt","Westminster Abbey und St Paul's Cathedral – prächtige Kirchen","Lebendige Viertel und Märkte – Soho, Covent Garden, Camden und Borough Market"]$j$::jsonb, $j$["In Tube und Bus zahlt man am einfachsten kontaktlos mit Karte oder Handy oder mit einer Oyster Card – durch den täglichen Preisdeckel zahlt man nie mehr als den Tagestarif.","Viele der besten Museen sind kostenlos, darunter das British Museum, die National Gallery, die Tate Modern und das Natural History Museum.","Für West-End-Musicals gibt es am TKTS-Stand am Leicester Square oft vergünstigte Tickets für denselben Tag.","Die ETA-Einreisegenehmigung sollte man rechtzeitig vor der Reise online beantragen; beim Überqueren der Straße wegen des Linksverkehrs zuerst nach rechts schauen."]$j$::jsonb, $j$[{"question":"Brauche ich für London ein Visum oder eine ETA?","answer":"Für touristische Aufenthalte benötigen deutsche Staatsbürger kein Visum, jedoch seit 2025 eine kostenpflichtige ETA (Electronic Travel Authorisation), die vorab online beantragt wird. Außerdem ist ein gültiger Reisepass nötig; der Personalausweis reicht für Touristen nicht mehr aus."},{"question":"Wann ist die beste Reisezeit für London?","answer":"Am angenehmsten ist es von Mai bis September mit mildem Wetter und langen Tagen. Der Dezember ist mit festlicher Weihnachtsbeleuchtung besonders stimmungsvoll. Regenschauer sind in London allerdings ganzjährig möglich."},{"question":"Welche Währung gilt in London?","answer":"In London zahlt man mit dem Britischen Pfund (GBP), nicht mit dem Euro. Kartenzahlung und kontaktloses Bezahlen sind nahezu überall üblich, sodass man kaum Bargeld benötigt."},{"question":"Wie reist man nach London an?","answer":"Am schnellsten geht es per Flug zu einem der Londoner Flughäfen wie Heathrow, Gatwick oder Stansted. Eine bequeme Alternative ist der Eurostar-Zug über Brüssel oder Paris, der im Zentrum am Bahnhof St Pancras hält."},{"question":"Braucht man in London ein Auto?","answer":"Nein, im Gegenteil. London hat mit der U-Bahn (Tube), Bussen und Bahnen einen hervorragenden Nahverkehr. Ein Auto ist wegen Linksverkehr, City-Maut (Congestion Charge) und teurer Parkplätze eher hinderlich."},{"question":"Wie nutzt man den Nahverkehr am besten?","answer":"Am einfachsten zahlt man kontaktlos mit Kreditkarte oder Smartphone, alternativ mit einer Oyster Card. Dank des täglichen Preisdeckels zahlt man nie mehr als den günstigsten Tagestarif für die genutzten Zonen."},{"question":"Sind die Museen in London wirklich kostenlos?","answer":"Ja, viele der bedeutendsten Museen verlangen keinen Eintritt, darunter das British Museum, die National Gallery, die Tate Modern und das Natural History Museum. Für Sonderausstellungen können jedoch Gebühren anfallen."},{"question":"Lohnt sich ein Musical im West End?","answer":"Auf jeden Fall. Das Londoner West End gilt neben dem Broadway als Welthauptstadt des Musicals. Vergünstigte Tickets gibt es am TKTS-Stand am Leicester Square oder online; beliebte Shows sollte man frühzeitig buchen."},{"question":"Ist London für Familien geeignet?","answer":"Ja, London ist sehr familienfreundlich. Das Natural History Museum, der Tower of London, das London Eye, Parks wie der Hyde Park sowie Attraktionen rund um beliebte Filmwelten begeistern Kinder. Vieles ist zudem kostenlos."},{"question":"Wie viele Tage sollte man für London einplanen?","answer":"Für die wichtigsten Highlights sollte man 3 bis 4 Tage einplanen. Wer tiefer in Museen, Viertel, Märkte und Tagesausflüge eintauchen möchte, kann gut 5 Tage oder mehr bleiben."}]$j$::jsonb, $t$London Städtereise: Big Ben, Tower, Tipps & beste Reisezeit$t$, $t$Deine London-Reise: Big Ben, der Tower of London, Buckingham Palace, kostenlose Museen und West-End-Musicals. Beste Reisezeit, Einreise mit ETA, Highlights und Tipps im Überblick.$t$, $t$London Städtereise buchen, Flug nach London, Hotel London, London Wochenende, Musical Tickets London, London Sehenswürdigkeiten Tickets, Eurostar London$t$, false, $j$["paris","amsterdam","schottland"]$j$::jsonb, ARRAY[$t$London$t$,$t$Vereinigtes Königreich$t$,$t$Themse$t$,$t$Big Ben$t$,$t$Houses of Parliament$t$,$t$Tower of London$t$,$t$Tower Bridge$t$,$t$Buckingham Palace$t$,$t$London Eye$t$,$t$British Museum$t$,$t$Westminster Abbey$t$,$t$West End$t$,$t$Covent Garden$t$,$t$Camden Market$t$,$t$Britisches Pfund$t$,$t$ETA$t$]::text[], $t$London ist eine pulsierende Weltmetropole an der Themse mit ikonischen Wahrzeichen wie Big Ben, dem Tower of London, Buckingham Palace und dem London Eye, weltberühmten kostenlosen Museen wie dem British Museum und den besten Musicals im West End. Mit exzellentem Nahverkehr, multikulturellem Flair und royaler Eleganz eignet sie sich ideal für einen Städtetrip und ist von Deutschland aus in kurzer Flugzeit oder per Eurostar erreichbar. Für die Einreise sind ein Reisepass und eine kostenpflichtige ETA-Genehmigung nötig, die beste Reisezeit liegt zwischen Mai und September.$t$, $t$London ist eine pulsierende Weltmetropole an der Themse mit Big Ben, dem Tower, Buckingham Palace, kostenlosen Museen und West-End-Musicals; zur Einreise braucht man Reisepass und ETA.$t$, $t$https://www.apearound.de/reiseziele/london$t$, $t$/images/destinations/london.jpg$t$, $t$/images/destinations/london.jpg$t$, $t$London Städtereise: Big Ben, Tower, Tipps & beste Reisezeit$t$, $t$Deine London-Reise: Big Ben, der Tower of London, Buckingham Palace, kostenlose Museen und West-End-Musicals. Beste Reisezeit, Einreise mit ETA, Highlights und Tipps im Überblick.$t$, $t$London Städtereise: Big Ben, Tower, Tipps & beste Reisezeit$t$, $t$Deine London-Reise: Big Ben, der Tower of London, Buckingham Palace, kostenlose Museen und West-End-Musicals. Beste Reisezeit, Einreise mit ETA, Highlights und Tipps im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Malaysia
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Malaysia$t$, $t$malaysia$t$, $t$Malaysia$t$, $t$Südostasien$t$, $t$Asien$t$, $t$/images/destinations/malaysia-hero.jpg$t$, $t$Vielfältiges Südostasien-Ziel mit moderner Skyline in Kuala Lumpur, multikultureller Streetfood-Kultur, Inselparadiesen und dem Dschungel Borneos.$t$, $t$Malaysia vereint auf faszinierende Weise Moderne, Multikulturalität und üppige Natur. Die Hauptstadt Kuala Lumpur beeindruckt mit den ikonischen Petronas Towers, den Batu Caves und einer pulsierenden Food-Szene. Die UNESCO-Stadt George Town auf Penang gilt als kulinarisches Herz des Landes, in dem malaiische, chinesische und indische Einflüsse zu einer einzigartigen Streetfood-Kultur verschmelzen. Strandliebhaber zieht es auf die Inseln Langkawi, Tioman und die Perhentians mit ihren Korallenriffen, während die Cameron Highlands mit kühlen Teeplantagen locken. Das eigentliche Naturwunder liegt auf der Insel Borneo: Im malaysischen Teil mit Sabah und Sarawak erlebt man Orang-Utans, den mächtigen Mount Kinabalu, dichten Regenwald und erstklassige Tauchgründe. Dazu kommt das geschichtsträchtige Malakka. Mit guter Infrastruktur, weit verbreitetem Englisch, fairen Preisen und enormer Vielfalt ist Malaysia ideal für Rundreisen, Strand-, Natur- und Kulturreisen.$t$, $t$Malaysia ist ein vielfältiges Reiseland in Südostasien mit der modernen Hauptstadt Kuala Lumpur, der Streetfood-Stadt George Town auf Penang, Inselparadiesen wie Langkawi und den Perhentians sowie dem Regenwald und den Orang-Utans Borneos. Es bietet gute Infrastruktur, weit verbreitetes Englisch und faire Preise und eignet sich ideal für Rundreisen, Strand-, Natur- und Kulturreisen.$t$, $t$Insgesamt sind die Monate Dezember bis April günstig. Wegen zweier Monsunküsten variiert es jedoch: Die Westküste mit Langkawi und Penang ist im Winter ideal, die Ostküsteninseln wie die Perhentians sind etwa von März bis Oktober am schönsten.$t$, $t$2 bis 3 Wochen$t$, ARRAY[$t$Rundreise$t$,$t$Strandurlaub$t$,$t$Städtereise$t$,$t$Kulinarik$t$,$t$Naturreise$t$,$t$Inselhüpfen$t$,$t$Familien$t$]::text[], $j${"currency":"Malaysischer Ringgit (MYR)","language":"Malaiisch (Bahasa Malaysia); Englisch ist weit verbreitet","flightTime":"ca. 12 bis 13 Stunden ab Deutschland, teils direkt nach Kuala Lumpur","timezone":"MYT (UTC+8), sieben Stunden vor MEZ","visa":"Visumfreier Aufenthalt bis 90 Tage; vor der Einreise ist die digitale Einreisekarte (MDAC) online auszufüllen","bestMonths":"Dezember bis April (Westküste)"}$j$::jsonb, $j$["Kuala Lumpur – Petronas Towers, Batu Caves und lebendige Food-Szene","George Town (Penang) – UNESCO-Welterbe, Streetfood und Street Art","Langkawi – Inselparadies mit Stränden, Sky Bridge und Mangroven","Perhentian-Inseln und Tioman – Korallenriffe zum Schnorcheln und Tauchen","Borneo (Sabah und Sarawak) – Orang-Utans, Regenwald und Mount Kinabalu","Cameron Highlands – kühle Teeplantagen und Wanderwege","Malakka – koloniale Geschichte und UNESCO-Altstadt","Taman Negara – einer der ältesten Regenwälder der Erde"]$j$::jsonb, $j$["George Town auf Penang gilt als Streetfood-Hauptstadt – an den Garküchen treffen malaiische, chinesische und indische Küche aufeinander; einfach durchprobieren.","Wer Orang-Utans und Spitzentauchen erleben möchte, sollte unbedingt einen Abstecher nach Borneo einplanen, etwa zur Auffangstation Sepilok und zur Tauchinsel Sipadan.","Da Malaysia zwei Monsunküsten hat, sollte man die Inselziele passend zur Jahreszeit wählen, um Regen und Wellengang zu vermeiden.","Für den Transport in den Städten ist die Grab-App praktisch, günstig und transparent, da der Preis vorab feststeht."]$j$::jsonb, $j$[{"question":"Brauche ich ein Visum für Malaysia?","answer":"Deutsche Staatsbürger können für touristische Aufenthalte bis zu 90 Tage visumfrei einreisen. Vor der Einreise ist jedoch die digitale Einreisekarte (Malaysia Digital Arrival Card, MDAC) online auszufüllen. Der Reisepass muss noch mindestens sechs Monate gültig sein."},{"question":"Wann ist die beste Reisezeit für Malaysia?","answer":"Insgesamt sind Dezember bis April günstig. Da das Land zwei Monsunküsten hat, gilt es zu unterscheiden: Die Westküste mit Langkawi und Penang ist im Winter ideal, die Ostküsteninseln wie die Perhentians etwa von März bis Oktober."},{"question":"Welche Währung gilt in Malaysia?","answer":"Gezahlt wird mit dem Malaysischen Ringgit (MYR). Kartenzahlung ist in Städten und Hotels weit verbreitet, an Märkten und Garküchen empfiehlt sich jedoch Bargeld. Geldautomaten sind problemlos verfügbar."},{"question":"Wie reist man am besten innerhalb Malaysias?","answer":"Günstige Inlandsflüge verbinden die Halbinsel mit Borneo und den Inseln, dazu gibt es komfortable Busse und Züge. In Städten ist die Grab-App praktisch. Inseln erreicht man per Fähre. Ein eigener Mietwagen ist meist nicht nötig."},{"question":"Lohnt sich ein Mietwagen in Malaysia?","answer":"Die Straßen sind gut ausgebaut, dennoch nutzen die meisten Reisenden Flüge, Busse und die Grab-App. Wer selbst fährt, sollte den Linksverkehr beachten. Für entlegene Regionen oder die Cameron Highlands kann ein Mietwagen praktisch sein."},{"question":"Was kann man auf Borneo erleben?","answer":"Der malaysische Teil Borneos mit Sabah und Sarawak ist berühmt für Orang-Utans (etwa in Sepilok), den 4.095 Meter hohen Mount Kinabalu, dichten Regenwald, Flusssafaris und erstklassiges Tauchen rund um Sipadan."},{"question":"Ist Malaysia für einen Familienurlaub geeignet?","answer":"Ja, Malaysia ist familienfreundlich und vielseitig. Strände, Tiererlebnisse, moderne Städte, gute Infrastruktur und weit verbreitetes Englisch machen es zu einem entspannten Ziel auch mit Kindern."},{"question":"Kann man in Malaysia das Leitungswasser trinken?","answer":"Das Leitungswasser ist meist gechlort, sollte aber zur Sicherheit nicht ungekocht getrunken werden. Üblich ist die Verwendung von abgefülltem oder abgekochtem Wasser."},{"question":"Welche Impfungen werden für Malaysia empfohlen?","answer":"Vorgeschrieben sind in der Regel keine Impfungen. Empfohlen werden Standardimpfungen sowie je nach Reiseart Hepatitis A und teils Typhus. Für eine individuelle Beratung sollte man rechtzeitig ein Tropeninstitut oder den Hausarzt aufsuchen."},{"question":"Spricht man in Malaysia Englisch?","answer":"Ja, Englisch ist sehr weit verbreitet und wird in Städten, Hotels und im Tourismus problemlos verstanden. Das macht die Verständigung für deutsche Reisende besonders einfach."},{"question":"Welche Gerichte sollte man in Malaysia probieren?","answer":"Typisch sind Nasi Lemak (das Nationalgericht), Laksa, Char Kway Teow, Satay sowie indische und chinesische Spezialitäten. Die multikulturelle Küche, besonders in Penang, ist ein echtes Highlight."},{"question":"Wie viele Tage sollte man für Malaysia einplanen?","answer":"Um Kuala Lumpur, Penang und eine Insel zu verbinden, reichen rund 10 Tage. Wer zusätzlich Borneo mit Orang-Utans und Tauchen erleben möchte, sollte 2 bis 3 Wochen einplanen."}]$j$::jsonb, $t$Malaysia Urlaub: Kuala Lumpur, Borneo, Tipps & beste Reisezeit$t$, $t$Dein Malaysia-Urlaub: Kuala Lumpur, die Streetfood-Stadt Penang, Inseln wie Langkawi und der Regenwald Borneos mit Orang-Utans. Beste Reisezeit, Visum, Highlights und Reisetipps im Überblick.$t$, $t$Malaysia Rundreise buchen, Flug nach Kuala Lumpur, Hotel Malaysia, Borneo Reise mit Orang-Utans, Strandurlaub Langkawi, Backpacking Südostasien$t$, false, $j$["thailand","singapur","indonesien"]$j$::jsonb, ARRAY[$t$Malaysia$t$,$t$Kuala Lumpur$t$,$t$Petronas Towers$t$,$t$Batu Caves$t$,$t$Penang$t$,$t$George Town$t$,$t$Langkawi$t$,$t$Perhentian-Inseln$t$,$t$Tioman$t$,$t$Borneo$t$,$t$Sabah$t$,$t$Sarawak$t$,$t$Mount Kinabalu$t$,$t$Cameron Highlands$t$,$t$Malakka$t$,$t$Malaysischer Ringgit$t$]::text[], $t$Malaysia ist ein vielfältiges Reiseland in Südostasien mit der modernen Hauptstadt Kuala Lumpur und ihren Petronas Towers, der multikulturellen Streetfood-Stadt George Town auf Penang, Inselparadiesen wie Langkawi und den Perhentians sowie dem Regenwald und den Orang-Utans Borneos. Es bietet gute Infrastruktur, weit verbreitetes Englisch und faire Preise und eignet sich ideal für Rundreisen, Strand-, Natur- und Kulturreisen. Deutsche Reisende können bis zu 90 Tage visumfrei einreisen.$t$, $t$Malaysia ist ein vielfältiges Südostasien-Ziel mit Kuala Lumpur, der Streetfood-Stadt Penang, Inseln wie Langkawi und dem Regenwald Borneos mit Orang-Utans.$t$, $t$https://www.apearound.de/reiseziele/malaysia$t$, $t$/images/destinations/malaysia.jpg$t$, $t$/images/destinations/malaysia.jpg$t$, $t$Malaysia Urlaub: Kuala Lumpur, Borneo, Tipps & beste Reisezeit$t$, $t$Dein Malaysia-Urlaub: Kuala Lumpur, die Streetfood-Stadt Penang, Inseln wie Langkawi und der Regenwald Borneos mit Orang-Utans. Beste Reisezeit, Visum, Highlights und Reisetipps im Überblick.$t$, $t$Malaysia Urlaub: Kuala Lumpur, Borneo, Tipps & beste Reisezeit$t$, $t$Dein Malaysia-Urlaub: Kuala Lumpur, die Streetfood-Stadt Penang, Inseln wie Langkawi und der Regenwald Borneos mit Orang-Utans. Beste Reisezeit, Visum, Highlights und Reisetipps im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Mallorca
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Mallorca$t$, $t$mallorca$t$, $t$Spanien$t$, $t$Balearische Inseln (Mittelmeer)$t$, $t$Europa$t$, $t$/images/destinations/mallorca-hero.jpg$t$, $t$Die beliebteste Insel der Deutschen mit türkisen Traumbuchten, dem Tramuntana-Gebirge, dem charmanten Palma, Mandelblüte und Lebensfreude – weit mehr als Ballermann.$t$, $t$Mallorca ist die größte der Balearischen Inseln und das mit Abstand beliebteste Urlaubsziel der Deutschen – nicht ohne Grund, denn die Insel ist erstaunlich vielfältig. Die quirlige Hauptstadt Palma beeindruckt mit der gewaltigen Kathedrale La Seu, einer charmanten Altstadt und einer lebendigen Gastro-Szene. Im Nordwesten erhebt sich die Serra de Tramuntana, ein UNESCO-Welterbe mit dramatischen Berglandschaften, alten Olivenhainen und pittoresken Dörfern wie Valldemossa, Deià und Sóller, das ein historischer Holzzug mit Palma verbindet. An den Küsten locken unzählige Traumbuchten mit türkisem Wasser, vom karibisch anmutenden Es Trenc bis zur kleinen Caló des Moro. Familien schätzen die flachen Strände rund um Alcúdia, Naturfreunde die Wanderwege und das Radrevier der Tramuntana, Feierfreudige die Partymeile am Ballermann. Im Februar verwandelt die Mandelblüte die Insel in ein rosa-weißes Blütenmeer. Mit kurzer Flugzeit, gutem Wetter und Angeboten für jeden Geschmack ist Mallorca ideal für Strand-, Familien-, Aktiv- und Genussurlaub.$t$, $t$Mallorca ist die beliebteste Insel der Deutschen und überrascht mit weit mehr als dem Ballermann: türkise Traumbuchten, das UNESCO-Gebirge Serra de Tramuntana, das charmante Palma mit der Kathedrale La Seu, malerische Bergdörfer und die Mandelblüte. Mit kurzer Flugzeit eignet es sich ideal für Strand-, Familien-, Aktiv- und Genussurlaub.$t$, $t$Mai bis Oktober für Strand und Badeurlaub; Frühling und Herbst sind ideal zum Wandern und Radfahren, und im Februar verzaubert die Mandelblüte die Insel.$t$, $t$Eine Woche$t$, ARRAY[$t$Strandurlaub$t$,$t$Familien$t$,$t$Wandern$t$,$t$Radreise$t$,$t$Wellness$t$,$t$Roadtrip$t$,$t$Partyurlaub$t$]::text[], $j${"currency":"Euro (EUR)","language":"Spanisch und Katalanisch (Mallorquí); Deutsch und Englisch sind weit verbreitet","flightTime":"ca. 2 bis 2,5 Stunden ab Deutschland (Palma de Mallorca)","timezone":"MEZ (UTC+1), identisch mit Deutschland","visa":"Nicht erforderlich für EU-Bürger (Schengen-Raum)","bestMonths":"Mai bis Oktober"}$j$::jsonb, $j$["Palma de Mallorca – die Kathedrale La Seu und die charmante Altstadt","Serra de Tramuntana – UNESCO-Gebirge mit Bergdörfern und Wanderwegen","Traumbuchten – von Es Trenc bis zur kleinen Caló des Moro","Sóller – Orangental mit historischem Holzzug ab Palma","Valldemossa und Deià – malerische Dörfer in den Bergen","Cap de Formentor – spektakulärer Aussichtspunkt an der Nordspitze","Coves del Drac – beeindruckende Tropfsteinhöhlen mit unterirdischem See","Playa de Palma und Ballermann – berühmte Strand- und Partymeile"]$j$::jsonb, $j$["Die schönsten Seiten Mallorcas entdeckt man abseits der Resorts mit dem Mietwagen – etwa die versteckten Calas und die Bergstraßen der Tramuntana.","Eine Fahrt mit dem historischen Holzzug von Palma nach Sóller und weiter mit der Straßenbahn zum Hafen ist ein nostalgisches Erlebnis.","Frühling und Herbst sind ideal zum Wandern und Radfahren; die Tramuntana ist ein weltbekanntes Trainingsrevier für Rennradfahrer.","Beliebte Fotobuchten wie Caló des Moro sind schnell überfüllt – früh am Morgen kommen lohnt sich, und der karibisch wirkende Es Trenc begeistert mit feinem Sand."]$j$::jsonb, $j$[{"question":"Wann ist die beste Reisezeit für Mallorca?","answer":"Für Strand und Baden eignen sich die Monate Mai bis Oktober. Frühling und Herbst sind ideal zum Wandern und Radfahren, da es dann angenehm mild ist. Im Februar lockt die Mandelblüte, und die Hochsaison im Hochsommer ist am vollsten."},{"question":"Wie reist man nach Mallorca an?","answer":"Am einfachsten per Flug zum Airport Palma de Mallorca, der von vielen deutschen Flughäfen in rund 2 bis 2,5 Stunden erreichbar ist. Vom Flughafen gelangt man mit Bus, Taxi oder Mietwagen schnell in die Urlaubsorte."},{"question":"Braucht man auf Mallorca einen Mietwagen?","answer":"Für einen reinen Strandurlaub im Hotel nicht zwingend, doch zum Entdecken der Buchten, Bergdörfer und der Tramuntana ist ein Mietwagen sehr empfehlenswert. In Palma selbst ist ein Auto eher hinderlich."},{"question":"Ist Mallorca nur etwas für Partyurlauber?","answer":"Nein, das ist ein Klischee. Der Ballermann ist nur ein kleiner Teil der Insel. Mallorca bietet ruhige Buchten, Wandern und Radfahren in der Tramuntana, Kultur in Palma, charmante Dörfer und feine Küche – etwas für jeden Geschmack."},{"question":"Welche Strände sind auf Mallorca besonders schön?","answer":"Zu den schönsten zählen der lange, feinsandige Es Trenc, die Buchten im Südosten wie Cala Mondragó und Caló des Moro sowie die familienfreundlichen Strände rund um Alcúdia und Playa de Muro im Norden."},{"question":"Ist Mallorca für einen Familienurlaub geeignet?","answer":"Ja, sehr. Flache Sandstrände, kinderfreundliche Hotels, Wasserparks und Ausflüge wie die Höhlen oder der Zug nach Sóller machen Mallorca zu einem idealen und unkomplizierten Familienziel mit kurzer Anreise."},{"question":"Kann man auf Mallorca gut wandern und Rad fahren?","answer":"Ja, besonders in der Serra de Tramuntana. Es gibt zahlreiche Wanderwege mit Meer- und Bergblick, und die Insel ist ein weltbekanntes Rennrad-Revier. Frühling und Herbst sind dafür die besten Jahreszeiten."},{"question":"Spricht man auf Mallorca Deutsch?","answer":"In den touristischen Orten wird sehr häufig Deutsch und Englisch gesprochen, sodass die Verständigung für deutsche Urlauber problemlos ist. Amtssprachen sind Spanisch und Katalanisch (Mallorquí)."},{"question":"Was ist die Mandelblüte auf Mallorca?","answer":"Im Februar blühen die unzähligen Mandelbäume der Insel und tauchen weite Landstriche in ein rosa-weißes Blütenmeer. Diese ruhige Nebensaison ist ideal für Wanderungen und ein besonderes Naturschauspiel."},{"question":"Wie viele Tage sollte man für Mallorca einplanen?","answer":"Für einen erholsamen Strandurlaub mit einigen Ausflügen eignet sich eine Woche. Wer die Insel intensiver mit Bergen, Buchten und Palma erkunden möchte, kann gut 10 bis 14 Tage bleiben."}]$j$::jsonb, $t$Mallorca Urlaub: Strände, Palma, Tramuntana & beste Reisezeit$t$, $t$Dein Mallorca-Urlaub: türkise Traumbuchten, das Tramuntana-Gebirge, das charmante Palma und die Mandelblüte – weit mehr als Ballermann. Beste Reisezeit, Anreise, Highlights und Tipps im Überblick.$t$, $t$Mallorca Urlaub buchen, Pauschalreise Mallorca, Flug nach Palma, Hotel Mallorca, Finca Mallorca, Mietwagen Mallorca, Familienurlaub Mallorca$t$, true, $j$["ibiza","menorca","spanien"]$j$::jsonb, ARRAY[$t$Mallorca$t$,$t$Balearische Inseln$t$,$t$Palma de Mallorca$t$,$t$Kathedrale La Seu$t$,$t$Serra de Tramuntana$t$,$t$Valldemossa$t$,$t$Deià$t$,$t$Sóller$t$,$t$Es Trenc$t$,$t$Caló des Moro$t$,$t$Cap de Formentor$t$,$t$Coves del Drac$t$,$t$Playa de Palma$t$,$t$Ballermann$t$,$t$Mandelblüte$t$,$t$Euro$t$]::text[], $t$Mallorca ist die größte Baleareninsel und das beliebteste Urlaubsziel der Deutschen – und weit mehr als der Ballermann: türkise Traumbuchten wie Es Trenc und Caló des Moro, das UNESCO-Gebirge Serra de Tramuntana mit malerischen Dörfern, das charmante Palma mit der Kathedrale La Seu und im Februar die Mandelblüte. Mit kurzer Flugzeit, gutem Wetter und Angeboten für jeden Geschmack eignet es sich ideal für Strand-, Familien-, Aktiv- und Genussurlaub. Die beste Reisezeit für Strand liegt zwischen Mai und Oktober, Frühling und Herbst eignen sich zum Wandern und Radfahren.$t$, $t$Mallorca ist die beliebteste Insel der Deutschen mit türkisen Traumbuchten, dem Tramuntana-Gebirge, dem charmanten Palma und der Mandelblüte – weit mehr als Ballermann.$t$, $t$https://www.apearound.de/reiseziele/mallorca$t$, $t$/images/destinations/mallorca.jpg$t$, $t$/images/destinations/mallorca.jpg$t$, $t$Mallorca Urlaub: Strände, Palma, Tramuntana & beste Reisezeit$t$, $t$Dein Mallorca-Urlaub: türkise Traumbuchten, das Tramuntana-Gebirge, das charmante Palma und die Mandelblüte – weit mehr als Ballermann. Beste Reisezeit, Anreise, Highlights und Tipps im Überblick.$t$, $t$Mallorca Urlaub: Strände, Palma, Tramuntana & beste Reisezeit$t$, $t$Dein Mallorca-Urlaub: türkise Traumbuchten, das Tramuntana-Gebirge, das charmante Palma und die Mandelblüte – weit mehr als Ballermann. Beste Reisezeit, Anreise, Highlights und Tipps im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Marokko
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Marokko$t$, $t$marokko$t$, $t$Marokko$t$, $t$Nordafrika$t$, $t$Afrika$t$, $t$/images/destinations/marokko-hero.jpg$t$, $t$Farbenprächtiges Land aus 1001 Nacht mit den Königsstädten Marrakesch und Fès, der Sahara, dem Atlasgebirge, der blauen Stadt Chefchaouen und orientalischem Flair.$t$, $t$Marokko ist ein faszinierendes Reiseland, das mit allen Sinnen erlebt wird – ein farbenprächtiger Mix aus Orient, Berberkultur und afrikanischem Charme. In der quirligen Königsstadt Marrakesch verliert man sich in den Souks der Medina, erlebt das Spektakel auf dem Platz Jemaa el-Fnaa und entspannt im Jardin Majorelle. Fès beherbergt die größte und älteste Medina der arabischen Welt mit ihren berühmten Gerbereien. Im Süden lockt die Sahara: In Merzouga reitet man auf Kamelen über die goldenen Dünen des Erg Chebbi und übernachtet unter dem Sternenhimmel in einem Wüstencamp. Das Hohe Atlasgebirge mit Berberdörfern und der spektakulären Lehmfestung Aït-Ben-Haddou bietet großartige Landschaften, während die blaue Stadt Chefchaouen und die entspannte Küstenstadt Essaouira zu den schönsten Orten zählen. Dazu kommen Minztee, würzige Tajines und herzliche Gastfreundschaft. Marokko ist gut erreichbar, günstig und ideal für Rundreisen, Kultur- und Abenteuerurlaub.$t$, $t$Marokko ist ein farbenprächtiges nordafrikanisches Reiseland mit den Königsstädten Marrakesch und Fès, der Sahara bei Merzouga, dem Atlasgebirge, der blauen Stadt Chefchaouen und der Küstenstadt Essaouira. Es bietet orientalisches Flair, Berberkultur und herzliche Gastfreundschaft und eignet sich ideal für Rundreisen, Kultur- und Abenteuerurlaube.$t$, $t$Frühling (März bis Mai) und Herbst (September bis November) für angenehme Temperaturen; der Hochsommer ist im Landesinneren und in der Sahara extrem heiß, die Küste bleibt milder.$t$, $t$1 bis 2 Wochen$t$, ARRAY[$t$Rundreise$t$,$t$Kulturreise$t$,$t$Städtereise$t$,$t$Abenteuer$t$,$t$Wüstentour$t$,$t$Strandurlaub$t$,$t$Backpacking$t$]::text[], $j${"currency":"Marokkanischer Dirham (MAD); geschlossene Währung, die am besten erst vor Ort gewechselt wird","language":"Arabisch und Berberisch (Amazigh); Französisch ist weit verbreitet","flightTime":"ca. 3,5 bis 4 Stunden ab Deutschland (Marrakesch, Agadir)","timezone":"UTC+1, meist gleich der MEZ; während des Ramadan gilt UTC+0","visa":"Nicht erforderlich für deutsche Staatsbürger (Aufenthalt bis 90 Tage)","bestMonths":"März bis Mai sowie September bis November"}$j$::jsonb, $j$["Marrakesch – Medina, der Platz Jemaa el-Fnaa, Souks und der Jardin Majorelle","Fès – die größte und älteste Medina der arabischen Welt mit ihren Gerbereien","Sahara bei Merzouga – Kamelritte über die Dünen des Erg Chebbi und Nächte im Wüstencamp","Atlasgebirge – Berberdörfer, Wanderungen und der Gipfel Toubkal","Aït-Ben-Haddou – berühmte Lehmfestung und UNESCO-Welterbe","Chefchaouen – die blau getünchte Stadt im Rif-Gebirge","Essaouira – entspannte Küstenstadt mit Wind, Festung und Hafenflair","Casablanca – die imposante Hassan-II.-Moschee am Atlantik"]$j$::jsonb, $j$["Am authentischsten übernachtet man in einem Riad, einem traditionellen Stadthaus mit Innenhof, mitten in der Medina.","Eine Übernachtung in der Wüste bei Merzouga mit Kamelritt, Sonnenuntergang über den Dünen und Sternenhimmel ist ein unvergessliches Highlight.","In den Souks gehört Handeln fest zur Kultur – mit Geduld, einem Lächeln und etwas Humor erzielt man die besten Preise.","Der Dirham ist eine geschlossene Währung: Am besten wechselt man erst vor Ort und gibt restliches Bargeld vor der Ausreise wieder aus."]$j$::jsonb, $j$[{"question":"Brauche ich ein Visum für Marokko?","answer":"Nein, deutsche Staatsbürger benötigen für touristische Aufenthalte bis zu 90 Tage kein Visum. Der Reisepass muss bei der Einreise noch mindestens sechs Monate gültig sein."},{"question":"Wann ist die beste Reisezeit für Marokko?","answer":"Ideal sind Frühling (März bis Mai) und Herbst (September bis November) mit angenehmen Temperaturen. Der Hochsommer ist im Landesinneren und in der Sahara extrem heiß, während die Atlantikküste rund um Agadir und Essaouira ganzjährig milder bleibt."},{"question":"Welche Währung gilt in Marokko?","answer":"Gezahlt wird mit dem Marokkanischen Dirham (MAD). Es handelt sich um eine geschlossene Währung, die man im Ausland kaum bekommt und nicht ausführen sollte. Am besten wechselt man vor Ort oder hebt am Automaten ab. Bargeld ist auf Märkten wichtig."},{"question":"Sollte man in Marokko selbst Auto fahren?","answer":"Für die Küste und den Atlas ist Selbstfahren möglich, in den Städten ist der Verkehr jedoch chaotisch und Medinas sind autofrei. Viele Reisende setzen daher auf Züge zwischen den Städten sowie private Fahrer oder geführte Touren, besonders für die Wüste."},{"question":"Wie sicher ist Marokko für Reisende?","answer":"Marokko gilt als überwiegend sicheres und gastfreundliches Reiseland. In den Medinas sollte man auf Taschendiebstahl achten und mit aufdringlichen Verkäufern oder selbsternannten Führern freundlich, aber bestimmt umgehen. Aktuelle Hinweise des Auswärtigen Amts beachten."},{"question":"Welche Städte sollte man in Marokko besuchen?","answer":"Zu den Höhepunkten zählen die Königsstädte Marrakesch und Fès, die blaue Stadt Chefchaouen, die Küstenstadt Essaouira sowie Casablanca mit der Hassan-II.-Moschee. Auch Meknès und Rabat lohnen sich."},{"question":"Wie erlebt man die Sahara in Marokko am besten?","answer":"Beliebt ist eine mehrtägige Tour ab Marrakesch nach Merzouga zu den Dünen des Erg Chebbi, oft mit Übernachtung in einem Wüstencamp, Kamelritt und Sonnenaufgang über den Dünen."},{"question":"Kann man in Marokko das Leitungswasser trinken?","answer":"Nein, das Leitungswasser ist nicht zum Trinken geeignet. Man sollte abgefülltes Wasser verwenden und bei Eiswürfeln sowie ungeschältem Obst vorsichtig sein."},{"question":"Welche Kleidung ist in Marokko angemessen?","answer":"Marokko ist ein muslimisch geprägtes Land, daher empfiehlt sich besonders außerhalb von Touristenorten und Stränden eher bedeckte, respektvolle Kleidung. Für Frauen sind locker sitzende Kleidung sowie bedeckte Schultern und Knie sinnvoll."},{"question":"Welche Spezialitäten sollte man in Marokko probieren?","answer":"Typisch sind Tajine (Schmorgericht aus dem Tontopf), Couscous, Pastilla, Harira-Suppe und gegrillte Spieße. Dazu gehört der allgegenwärtige süße Minztee, der als Zeichen der Gastfreundschaft serviert wird."},{"question":"Ist Marokko für einen Familienurlaub geeignet?","answer":"Ja, Marokko kann mit Kindern bereichernd sein, etwa durch Kamelritte, bunte Souks und Strände bei Agadir. Wegen Hitze, Verkehr und langen Fahrstrecken sollte man die Route jedoch entspannt und kindgerecht planen."},{"question":"Wie viele Tage sollte man für Marokko einplanen?","answer":"Für eine Stadt wie Marrakesch reichen einige Tage. Für eine Rundreise mit Königsstädten, Atlas und Wüste sollte man 1 bis 2 Wochen einplanen, da die Distanzen groß sind."}]$j$::jsonb, $t$Marokko Urlaub: Marrakesch, Sahara, Tipps & beste Reisezeit$t$, $t$Dein Marokko-Urlaub: die Königsstädte Marrakesch und Fès, die Sahara bei Merzouga, das Atlasgebirge und die blaue Stadt Chefchaouen. Beste Reisezeit, Highlights und praktische Reisetipps im Überblick.$t$, $t$Marokko Reise buchen, Flug und Hotel Marrakesch, Riad Marrakesch, Wüstentour Merzouga, Rundreise Marokko, Mietwagen oder Privatfahrer Marokko$t$, false, $j$["aegypten","tunesien","tuerkei"]$j$::jsonb, ARRAY[$t$Marokko$t$,$t$Marrakesch$t$,$t$Jemaa el-Fnaa$t$,$t$Medina$t$,$t$Fès$t$,$t$Sahara$t$,$t$Merzouga$t$,$t$Erg Chebbi$t$,$t$Atlasgebirge$t$,$t$Aït-Ben-Haddou$t$,$t$Chefchaouen$t$,$t$Essaouira$t$,$t$Casablanca$t$,$t$Hassan-II.-Moschee$t$,$t$Tajine$t$,$t$Marokkanischer Dirham$t$]::text[], $t$Marokko ist ein farbenprächtiges nordafrikanisches Reiseland mit den Königsstädten Marrakesch und Fès, der Sahara bei Merzouga, dem Hohen Atlasgebirge, der blauen Stadt Chefchaouen und der Küstenstadt Essaouira. Es bietet orientalisches Flair, Berberkultur, würzige Küche und herzliche Gastfreundschaft und eignet sich ideal für Rundreisen, Kultur- und Abenteuerurlaube. Die beste Reisezeit liegt im Frühling und Herbst.$t$, $t$Marokko ist ein farbenprächtiges Land mit den Königsstädten Marrakesch und Fès, der Sahara, dem Atlasgebirge und der blauen Stadt Chefchaouen.$t$, $t$https://www.apearound.de/reiseziele/marokko$t$, $t$/images/destinations/marokko.jpg$t$, $t$/images/destinations/marokko.jpg$t$, $t$Marokko Urlaub: Marrakesch, Sahara, Tipps & beste Reisezeit$t$, $t$Dein Marokko-Urlaub: die Königsstädte Marrakesch und Fès, die Sahara bei Merzouga, das Atlasgebirge und die blaue Stadt Chefchaouen. Beste Reisezeit, Highlights und praktische Reisetipps im Überblick.$t$, $t$Marokko Urlaub: Marrakesch, Sahara, Tipps & beste Reisezeit$t$, $t$Dein Marokko-Urlaub: die Königsstädte Marrakesch und Fès, die Sahara bei Merzouga, das Atlasgebirge und die blaue Stadt Chefchaouen. Beste Reisezeit, Highlights und praktische Reisetipps im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Mexiko
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Mexiko$t$, $t$mexiko$t$, $t$Mexiko$t$, $t$Lateinamerika$t$, $t$Nordamerika$t$, $t$/images/destinations/mexiko-hero.jpg$t$, $t$Faszinierendes Reiseland mit Maya-Ruinen, Traumstränden an der Karibik, Cenoten, lebendiger Kultur und weltberühmter Küche.$t$, $t$Mexiko ist ein Land der Gegensätze und kulturellen Vielfalt – von den türkisblauen Karibikstränden der Riviera Maya über uralte Maya- und Azteken-Stätten bis zu den pulsierenden Straßen der Hauptstadt Mexiko-Stadt. Auf der Halbinsel Yucatán locken Weltwunder wie Chichén Itzá, die malerischen Klippenruinen von Tulum und die geheimnisvollen Cenoten, kristallklare Kalksteinquellen zum Schwimmen und Tauchen. Im Landesinneren beeindrucken die Pyramiden von Teotihuacán, koloniale Städte wie Guanajuato und die für ihre Küche berühmte Region Oaxaca. Mexiko ist zugleich ein kulinarisches Paradies: Tacos, Mole und frische Tortillas gehören zur lebendigen Esskultur, die zum UNESCO-Weltkulturerbe zählt. Ob Strandurlaub, Rundreise, Tauchen oder Kulturtrip – Mexiko bietet für jeden Reisetyp unvergessliche Erlebnisse.$t$, $t$Mexiko ist ein vielseitiges Reiseland in Nordamerika mit Maya-Ruinen wie Chichén Itzá und Tulum, den Karibikstränden der Riviera Maya, einzigartigen Cenoten und der lebendigen Hauptstadt Mexiko-Stadt. Es vereint Strandurlaub, Kultur, Abenteuer und eine weltberühmte Küche und eignet sich besonders gut für Rundreisen.$t$, $t$Die beste Reisezeit ist die Trockenzeit von November bis April mit angenehmen Temperaturen und wenig Regen; von Juni bis Oktober besteht in der Karibik Hurrikan-Saison.$t$, $t$Strandurlaub 1 bis 2 Wochen, Rundreise 2 bis 3 Wochen$t$, ARRAY[$t$Strandurlaub$t$,$t$Rundreise$t$,$t$Kulturreise$t$,$t$Tauchen$t$,$t$Abenteuer$t$,$t$Backpacking$t$,$t$Familien$t$]::text[], $j${"currency":"Mexikanischer Peso (MXN)","language":"Spanisch","flightTime":"ca. 11 bis 13 Stunden ab Deutschland (Cancún rund 11 Stunden)","timezone":"Mehrere Zeitzonen (UTC−5 bis UTC−7); Zentralmexiko UTC−6, sieben Stunden hinter MEZ","visa":"Für Touristen kein Visum nötig (Aufenthalt bis 180 Tage); bei Einreise wird eine Touristenkarte ausgestellt","bestMonths":"November bis April"}$j$::jsonb, $j$["Chichén Itzá – berühmte Maya-Pyramide und eines der neuen Weltwunder","Tulum – malerische Maya-Ruinen direkt über dem türkisfarbenen Karibikmeer","Cenoten in Yucatán – kristallklare Kalksteinquellen zum Schwimmen und Tauchen","Riviera Maya und Cancún – endlose Karibikstrände mit weißem Sand","Mexiko-Stadt – pulsierende Hauptstadt mit Zócalo, Museen und Street Food","Teotihuacán – gewaltige Pyramidenanlage der Sonne und des Mondes","Oaxaca – Kulturstadt und kulinarisches Zentrum mit Mole und Mezcal","Isla Holbox und Cozumel – ruhige Inseln zum Schnorcheln und Tauchen"]$j$::jsonb, $j$["Cenoten am besten früh am Morgen besuchen, bevor die Tagestouren eintreffen – dann hat man das klare Wasser oft fast für sich allein.","Echtes mexikanisches Street Food wie Tacos al Pastor schmeckt an den kleinen Ständen authentischer und günstiger als in touristischen Restaurants.","Wer Anfang November reist, erlebt mit dem Día de Muertos (Tag der Toten) eines der farbenprächtigsten und stimmungsvollsten Feste des Landes.","Für günstige Kurzstrecken nutzt man die Sammeltaxis (Colectivos), die zwischen vielen Orten der Riviera Maya verkehren."]$j$::jsonb, $j$[{"question":"Wann ist die beste Reisezeit für Mexiko?","answer":"Ideal ist die Trockenzeit von November bis April mit viel Sonne und angenehmen Temperaturen. Von Juni bis Oktober ist Regenzeit, und an der Karibikküste besteht zwischen Juni und November ein Hurrikan-Risiko."},{"question":"Brauche ich ein Visum für Mexiko?","answer":"Für touristische Aufenthalte bis zu 180 Tagen benötigen deutsche Staatsbürger kein Visum. Bei der Einreise erhält man eine Touristenkarte (FMM). Der Reisepass muss für die Dauer des Aufenthalts gültig sein."},{"question":"Welche Währung gilt in Mexiko?","answer":"Gezahlt wird mit dem Mexikanischen Peso (MXN). In touristischen Orten werden teils auch US-Dollar akzeptiert, der Kurs ist dann aber oft ungünstiger. Kartenzahlung ist in Städten verbreitet, für Märkte und Trinkgeld empfiehlt sich Bargeld."},{"question":"Wie sicher ist eine Reise nach Mexiko?","answer":"Die klassischen Touristenregionen wie die Riviera Maya, Yucatán und die kolonialen Städte gelten als gut bereisbar. Vor einer Reise sollte man jedoch stets die aktuellen Sicherheitshinweise des Auswärtigen Amts prüfen, da einzelne Bundesstaaten als gefährlicher eingestuft werden."},{"question":"Kann man in Mexiko das Leitungswasser trinken?","answer":"Nein, Leitungswasser ist in der Regel nicht zum Trinken geeignet. Man sollte auf abgefülltes Wasser zurückgreifen und auch beim Zähneputzen besser Flaschenwasser verwenden."},{"question":"Wie lange dauert der Flug nach Mexiko?","answer":"Ein Direktflug von Deutschland nach Cancún dauert etwa 11 Stunden, nach Mexiko-Stadt rund 12 bis 13 Stunden. Es gibt mehrere Direktverbindungen sowie Flüge mit Zwischenstopp."},{"question":"Lohnt sich ein Mietwagen in Mexiko?","answer":"Für eine individuelle Rundreise auf der Halbinsel Yucatán ist ein Mietwagen sehr praktisch, um Cenoten, Ruinen und kleinere Orte flexibel zu erreichen. Wer ausschließlich im Strandresort bleibt, kommt auch ohne Auto aus."},{"question":"Was sind Cenoten?","answer":"Cenoten sind natürliche, mit Süßwasser gefüllte Kalksteinlöcher, die vor allem auf Yucatán verbreitet sind. Sie galten den Maya als heilig und sind heute beliebte Orte zum Schwimmen, Schnorcheln und Tauchen."},{"question":"Welche typischen Gerichte sollte man in Mexiko probieren?","answer":"Unbedingt probieren sollte man Tacos al Pastor, Guacamole, Tamales, Mole, Quesadillas und frische Tortillas. Die mexikanische Küche zählt zum UNESCO-Weltkulturerbe und ist deutlich vielfältiger als das im Ausland bekannte Tex-Mex."},{"question":"Welche Impfungen brauche ich für Mexiko?","answer":"Vorgeschrieben sind in der Regel keine Impfungen. Empfohlen werden Standardimpfungen sowie je nach Reiseart Hepatitis A und teils Typhus. Für eine individuelle Beratung sollte man rechtzeitig ein Tropeninstitut oder den Hausarzt aufsuchen."},{"question":"Ist Mexiko für einen Familienurlaub geeignet?","answer":"Ja, besonders die Riviera Maya bietet familienfreundliche Strände, Resorts und Erlebnisparks wie Xcaret und Xel-Há. Cenoten, Tierbeobachtungen und Maya-Ruinen sorgen für Abwechslung bei Groß und Klein."},{"question":"Wie viel Zeit sollte man für eine Mexiko-Reise einplanen?","answer":"Für einen reinen Strandurlaub reichen 1 bis 2 Wochen. Wer Kultur, Ruinen, Cenoten und mehrere Regionen verbinden möchte, sollte für eine Rundreise 2 bis 3 Wochen einplanen."}]$j$::jsonb, $t$Mexiko Urlaub: Reisetipps, Maya-Ruinen, Strände & beste Reisezeit$t$, $t$Dein Mexiko-Urlaub: Maya-Stätten wie Chichén Itzá und Tulum, Karibikstrände, Cenoten und Mexiko-Stadt. Beste Reisezeit, Highlights, Sicherheit und praktische Tipps im Überblick.$t$, $t$Mexiko Rundreise buchen, Flug und Hotel Cancún oder Riviera Maya, Mietwagen Yucatán vergleichen, All-Inclusive Mexiko, Ausflüge Chichén Itzá und Cenoten$t$, true, $j$["kuba","costa-rica","guatemala"]$j$::jsonb, ARRAY[$t$Mexiko$t$,$t$Yucatán$t$,$t$Chichén Itzá$t$,$t$Tulum$t$,$t$Cancún$t$,$t$Riviera Maya$t$,$t$Cenoten$t$,$t$Mexiko-Stadt$t$,$t$Teotihuacán$t$,$t$Oaxaca$t$,$t$Cozumel$t$,$t$Isla Holbox$t$,$t$Maya$t$,$t$Tacos al Pastor$t$,$t$Día de Muertos$t$,$t$Mexikanischer Peso$t$]::text[], $t$Mexiko ist ein vielseitiges Reiseland in Nordamerika, bekannt für seine Maya-Ruinen wie Chichén Itzá und Tulum, die Karibikstrände der Riviera Maya, die einzigartigen Cenoten und die lebendige Hauptstadt Mexiko-Stadt. Es verbindet Strandurlaub, Kultur, Abenteuer und eine weltberühmte Küche und eignet sich besonders für Rundreisen. Die beste Reisezeit liegt in der Trockenzeit von November bis April.$t$, $t$Mexiko ist ein vielseitiges Reiseland mit Maya-Ruinen, Karibikstränden, Cenoten und weltberühmter Küche, am besten von November bis April zu bereisen.$t$, $t$https://www.apearound.de/reiseziele/mexiko$t$, $t$/images/destinations/mexiko.jpg$t$, $t$/images/destinations/mexiko.jpg$t$, $t$Mexiko Urlaub: Reisetipps, Maya-Ruinen, Strände & beste Reisezeit$t$, $t$Dein Mexiko-Urlaub: Maya-Stätten wie Chichén Itzá und Tulum, Karibikstrände, Cenoten und Mexiko-Stadt. Beste Reisezeit, Highlights, Sicherheit und praktische Tipps im Überblick.$t$, $t$Mexiko Urlaub: Reisetipps, Maya-Ruinen, Strände & beste Reisezeit$t$, $t$Dein Mexiko-Urlaub: Maya-Stätten wie Chichén Itzá und Tulum, Karibikstrände, Cenoten und Mexiko-Stadt. Beste Reisezeit, Highlights, Sicherheit und praktische Tipps im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Monument Valley
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Monument Valley$t$, $t$monument-valley$t$, $t$Vereinigte Staaten (USA)$t$, $t$Arizona / Utah (Navajo Nation, USA-Südwesten)$t$, $t$Nordamerika$t$, $t$/images/destinations/monument-valley-hero.jpg$t$, $t$Das ikonische Bild des Wilden Westens: gewaltige rote Sandstein-Tafelberge, die einsam aus der Wüste an der Grenze von Arizona und Utah aufragen.$t$, $t$Monument Valley ist eine der berühmtesten Landschaften der Erde und das Sinnbild des amerikanischen Westens schlechthin. In der weiten roten Wüste an der Grenze zwischen Arizona und Utah ragen gewaltige Sandstein-Tafelberge (Buttes) und Mesas bis zu mehrere hundert Meter empor – allen voran die markanten „Mittens“ (Left und Right Mitten) und der Merrick Butte. Bekannt wurde die Kulisse durch zahllose Westernfilme, etwa von Regisseur John Ford, sowie durch den berühmten „Forrest Gump Point“ am Highway 163. Wichtig zu wissen: Monument Valley ist kein US-Nationalpark, sondern ein Navajo Tribal Park, der von der Navajo Nation verwaltet wird – mit eigener Eintrittsregelung und tiefer kultureller Bedeutung für das Volk der Diné. Über die rund 27 Kilometer lange Schotterpiste des Valley Drive lassen sich viele der berühmten Formationen mit dem eigenen Fahrzeug erkunden, während abgelegenere Bereiche nur mit einem Navajo-Guide zugänglich sind. Bei Sonnenauf- und -untergang glühen die Felsen tiefrot. Monument Valley ist ein unverzichtbarer Stopp auf jedem Südwesten-Roadtrip.$t$, $t$Monument Valley an der Grenze von Arizona und Utah ist mit seinen gewaltigen roten Sandstein-Tafelbergen das ikonische Bild des amerikanischen Westens und aus zahlreichen Filmen bekannt. Es ist kein Nationalpark, sondern ein Navajo Tribal Park mit eigener Eintrittsregelung. Der Ort eignet sich ideal als Stopp auf einem Südwesten-Roadtrip; für die Einreise gelten die USA-Bestimmungen mit ESTA.$t$, $t$Frühling (April bis Mai) und Herbst (September bis Oktober) mit mildem Wetter sind ideal. Der Sommer ist heiß, der Winter kühl und bisweilen verschneit, was die roten Felsen besonders fotogen macht.$t$, $t$Ein halber bis ganzer Tag, meist als Stopp auf einem Südwesten-Roadtrip$t$, ARRAY[$t$Naturreise$t$,$t$Roadtrip$t$,$t$Fotoreise$t$,$t$Kulturreise$t$,$t$Abenteuer$t$,$t$Familien$t$]::text[], $j${"currency":"US-Dollar (USD)","language":"Englisch sowie Navajo (Diné)","flightTime":"Kein Direktflug; sehr abgelegen. Ab Deutschland ca. 11 bis 12 Stunden in die USA plus lange Fahrt. Nächste Flughäfen: Flagstaff (rund 3,5 Stunden), Phoenix oder Las Vegas (jeweils mehrere Stunden Fahrt)","timezone":"Mountain Time; die Navajo Nation stellt – anders als das übrige Arizona – auf Sommerzeit um (Sommer UTC−6, Winter UTC−7)","visa":"Wie für die USA: kein Visum für Touristen (bis 90 Tage), aber elektronischer Reisepass und kostenpflichtige ESTA-Genehmigung erforderlich","bestMonths":"April bis Mai sowie September bis Oktober"}$j$::jsonb, $j$["Die „Mittens“ – Left und Right Mitten Butte, die berühmtesten Felsformationen","Merrick Butte – markanter Tafelberg neben den Mittens","Forrest Gump Point – ikonischer Fotostopp am Highway 163","Valley Drive – rund 27 Kilometer Schotterpiste durch das Tal","John Ford's Point – klassischer Aussichts- und Filmschauplatz","Navajo-geführte Touren in abgelegene, sonst gesperrte Bereiche","Sonnenauf- und -untergang, wenn die Buttes tiefrot erglühen","The View – Aussichtspunkt und Hotel mit Panoramablick über das Tal"]$j$::jsonb, $j$["Sonnenauf- und -untergang sind die magischsten Momente – dann färben sich die Tafelberge in tiefem Rot, ideal für Fotos.","Den Valley Drive (rund 27 km Schotterpiste) kann man mit dem eigenen Fahrzeug befahren; ein höhergelegtes Auto ist von Vorteil. Abgelegene Bereiche sind nur im Rahmen einer Navajo-geführten Tour zugänglich.","Monument Valley ist ein Navajo Tribal Park, kein Nationalpark: Es gilt eine eigene Eintrittsgebühr, und der „America the Beautiful“-Nationalpark-Pass wird hier nicht akzeptiert.","Das ikonische Foto der ins Tal führenden Straße entsteht am Forrest Gump Point am Highway 163 – beim Fotografieren unbedingt auf den Verkehr achten."]$j$::jsonb, $j$[{"question":"Ist Monument Valley ein Nationalpark?","answer":"Nein. Anders als der Name oft vermuten lässt, ist Monument Valley kein US-Nationalpark, sondern ein Navajo Tribal Park, der von der Navajo Nation verwaltet wird. Daher gelten eine eigene Eintrittsgebühr und eigene Regeln, und der Nationalpark-Jahrespass ist hier nicht gültig."},{"question":"Wann ist die beste Reisezeit für Monument Valley?","answer":"Am angenehmsten sind Frühling (April bis Mai) und Herbst (September bis Oktober) mit mildem Wetter. Der Sommer ist heiß, der Winter kühl und gelegentlich verschneit, was die roten Felsen besonders reizvoll macht."},{"question":"Was kostet der Eintritt und gilt der Nationalpark-Pass?","answer":"Monument Valley erhebt als Navajo Tribal Park eine eigene Eintrittsgebühr pro Fahrzeug. Der „America the Beautiful“-Nationalpark-Pass wird hier nicht akzeptiert, da der Park nicht zum US-Nationalparksystem gehört."},{"question":"Wie reist man nach Monument Valley an?","answer":"Monument Valley liegt sehr abgelegen. Üblich ist die Anfahrt mit dem Mietwagen im Rahmen eines Südwesten-Roadtrips. Die nächsten Flughäfen wie Flagstaff, Phoenix oder Las Vegas sind mehrere Stunden entfernt."},{"question":"Braucht man in Monument Valley einen Mietwagen?","answer":"Ja, wegen der abgelegenen Lage ist ein Mietwagen praktisch unverzichtbar. Den Valley Drive kann man selbst befahren; für abgelegenere Bereiche bietet sich eine geführte Navajo-Tour an, die zugleich kulturelle Einblicke vermittelt."},{"question":"Kann man Monument Valley auf eigene Faust erkunden?","answer":"Teilweise: Der rund 27 Kilometer lange Valley Drive ist mit dem eigenen Fahrzeug befahrbar, am besten mit einem höhergelegten Auto. Viele abgelegene Formationen und Slot Canyons sind jedoch nur mit einem autorisierten Navajo-Guide zugänglich."},{"question":"Brauche ich für Monument Valley ein Visum?","answer":"Es gelten die Einreisebestimmungen der USA: Für touristische Aufenthalte bis 90 Tage ist kein Visum nötig, aber ein elektronischer Reisepass und eine vorab beantragte, kostenpflichtige ESTA-Genehmigung. Details finden sich auf der USA-Seite."},{"question":"Worauf muss man bei der Zeitzone achten?","answer":"Eine Besonderheit: Die Navajo Nation stellt im Gegensatz zum übrigen Arizona auf Sommerzeit um. Im Sommer kann es daher zu Zeitunterschieden zwischen Monument Valley und dem restlichen Arizona kommen, was man bei Touren und Öffnungszeiten beachten sollte."},{"question":"Wo übernachtet man in Monument Valley?","answer":"Direkt am Park liegt das Hotel „The View“ mit Panoramablick auf die Mittens. Eine weitere bekannte Option ist die historische Goulding's Lodge. Beide sind beliebt und sollten früh gebucht werden; alternativ übernachtet man in Orten entlang der Route."},{"question":"Ist Monument Valley für Familien geeignet?","answer":"Ja, der Ort ist familienfreundlich. Der Valley Drive, die Aussichtspunkte und geführte Touren sind auch mit Kindern gut machbar. Wegen der Abgeschiedenheit und Hitze im Sommer sollte man ausreichend Wasser und Vorräte mitnehmen."},{"question":"Wie viel Zeit sollte man für Monument Valley einplanen?","answer":"Für den Valley Drive und die Aussichtspunkte reicht ein halber bis ganzer Tag. Wer Sonnenauf- oder -untergang und eine geführte Tour erleben möchte, plant eine Übernachtung vor Ort ein."}]$j$::jsonb, $t$Monument Valley: Tafelberge, Tipps & beste Reisezeit$t$, $t$Dein Besuch in Monument Valley an der Grenze von Arizona und Utah: ikonische rote Tafelberge, der Valley Drive, Forrest Gump Point und Navajo-Touren. Beste Reisezeit, Eintritt, Anreise und Tipps im Überblick.$t$, $t$Monument Valley Reise buchen, Mietwagen USA-Südwesten, Hotel The View Monument Valley, Navajo Tour Monument Valley, Rundreise Südwesten USA, Roadtrip Arizona Utah$t$, true, $j$["grand-canyon","zion","antelope-canyon"]$j$::jsonb, ARRAY[$t$Monument Valley$t$,$t$Navajo Nation$t$,$t$Arizona$t$,$t$Utah$t$,$t$Buttes$t$,$t$Left Mitten$t$,$t$Right Mitten$t$,$t$Merrick Butte$t$,$t$Forrest Gump Point$t$,$t$Valley Drive$t$,$t$John Ford's Point$t$,$t$The View$t$,$t$Goulding's Lodge$t$,$t$Highway 163$t$,$t$Navajo Tribal Park$t$,$t$USA-Südwesten$t$]::text[], $t$Monument Valley an der Grenze von Arizona und Utah ist mit seinen gewaltigen roten Sandstein-Tafelbergen wie den „Mittens“ das ikonische Bild des amerikanischen Westens und aus zahlreichen Filmen bekannt. Es ist kein US-Nationalpark, sondern ein von der Navajo Nation verwalteter Tribal Park mit eigener Eintrittsregelung; über den rund 27 Kilometer langen Valley Drive lassen sich viele Formationen selbst erkunden, abgelegene Bereiche nur mit Navajo-Guide. Der Ort ist ein Höhepunkt jedes Südwesten-Roadtrips, am schönsten bei Sonnenauf- und -untergang; für die Einreise gelten die USA-Bestimmungen mit ESTA.$t$, $t$Monument Valley an der Grenze von Arizona und Utah ist mit seinen roten Tafelbergen das ikonische Bild des Wilden Westens – ein Navajo Tribal Park, kein Nationalpark.$t$, $t$https://www.apearound.de/reiseziele/monument-valley$t$, $t$/images/destinations/monument-valley.jpg$t$, $t$/images/destinations/monument-valley.jpg$t$, $t$Monument Valley: Tafelberge, Tipps & beste Reisezeit$t$, $t$Dein Besuch in Monument Valley an der Grenze von Arizona und Utah: ikonische rote Tafelberge, der Valley Drive, Forrest Gump Point und Navajo-Touren. Beste Reisezeit, Eintritt, Anreise und Tipps im Überblick.$t$, $t$Monument Valley: Tafelberge, Tipps & beste Reisezeit$t$, $t$Dein Besuch in Monument Valley an der Grenze von Arizona und Utah: ikonische rote Tafelberge, der Valley Drive, Forrest Gump Point und Navajo-Touren. Beste Reisezeit, Eintritt, Anreise und Tipps im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- München
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$München$t$, $t$muenchen$t$, $t$Deutschland$t$, $t$Bayern$t$, $t$Europa$t$, $t$/images/destinations/muenchen-hero.jpg$t$, $t$Bayerns charmante Hauptstadt mit Marienplatz, Biergärten, dem Englischen Garten, dem Oktoberfest, royaler Pracht und den Alpen direkt vor der Haustür.$t$, $t$München ist die Hauptstadt Bayerns und verbindet weltstädtisches Flair mit bayerischer Gemütlichkeit wie keine andere deutsche Stadt. Im Herzen liegt der Marienplatz mit dem prächtigen Neuen Rathaus, dessen Glockenspiel täglich die Besucher verzaubert, überragt von den markanten Zwiebeltürmen der Frauenkirche. Royale Pracht erlebt man in der Residenz und im weitläufigen Schloss Nymphenburg. Der riesige Englische Garten lädt zum Flanieren ein – hier surfen mutige Wellenreiter auf der stehenden Welle des Eisbachs, und in den Biergärten am Chinesischen Turm genießt man Brotzeit und frisch Gezapftes. Das traditionsreiche Hofbräuhaus und der Viktualienmarkt verkörpern die Münchner Lebensart, während das Deutsche Museum, die Pinakotheken und die BMW Welt für Abwechslung sorgen. Weltberühmt ist das Oktoberfest, das größte Volksfest der Welt. Und wer Natur sucht, erreicht die Alpen und Seen wie den Tegernsee oder Schlösser wie Neuschwanstein bei einem Tagesausflug. München ist ein ideales Ziel für einen Städtetrip mit bayerischem Charme.$t$, $t$München ist Bayerns charmante Hauptstadt mit dem Marienplatz, der Frauenkirche, dem Englischen Garten mit Eisbach-Surfern, traditionsreichen Biergärten, royaler Pracht und dem weltberühmten Oktoberfest. Mit den Alpen vor der Haustür eignet sie sich ideal für einen Städtetrip mit bayerischem Flair und ist innerdeutsch sehr gut erreichbar.$t$, $t$Mai bis September mit mildem Wetter ist ideal für Biergärten und Sightseeing; das Oktoberfest findet von Mitte September bis Anfang Oktober statt, und im Advent locken stimmungsvolle Christkindlmärkte.$t$, $t$2 bis 3 Tage$t$, ARRAY[$t$Städtereise$t$,$t$Kulturreise$t$,$t$Wochenendtrip$t$,$t$Kulinarik$t$,$t$Familien$t$,$t$Shopping$t$]::text[], $j${"currency":"Euro (EUR)","language":"Deutsch (bairischer Dialekt)","flightTime":"Innerdeutsches Ziel; bequem per ICE oder Auto erreichbar, der Flughafen München (MUC) ist gut angebunden","timezone":"MEZ (UTC+1)","visa":"Nicht erforderlich (innerdeutsch bzw. für EU-Bürger im Schengen-Raum)","bestMonths":"Mai bis September"}$j$::jsonb, $j$["Marienplatz mit Neuem Rathaus und dem berühmten Glockenspiel","Frauenkirche – Wahrzeichen Münchens mit den markanten Zwiebeltürmen","Englischer Garten – Biergärten, Chinesischer Turm und die Eisbach-Surfer","Schloss Nymphenburg und die Residenz – royale Pracht","Oktoberfest – das größte Volksfest der Welt auf der Theresienwiese","Hofbräuhaus und Viktualienmarkt – bayerische Lebensart und Genuss","Deutsches Museum, Pinakotheken und BMW Welt – Wissenschaft, Kunst und Technik","Alpen und Schlösser – Tagesausflüge nach Neuschwanstein oder zu den Seen"]$j$::jsonb, $j$["Im Englischen Garten lohnt sich der Blick auf die Eisbachwelle, wo Surfer das ganze Jahr über auf einer stehenden Flusswelle reiten.","In vielen Biergärten darf man an Tischen ohne Bedienung eine eigene Brotzeit mitbringen – ein günstiges und typisch bayerisches Erlebnis.","Das Glockenspiel am Neuen Rathaus spielt täglich, meist um 11 und 12 Uhr; ein guter Blick gelingt vom Marienplatz oder vom Café gegenüber.","München ist ein idealer Ausgangspunkt für Tagesausflüge zum Schloss Neuschwanstein, an die Seen und in die Alpen; für den Nahverkehr lohnt sich ein MVV-Tagesticket."]$j$::jsonb, $j$[{"question":"Wann ist die beste Reisezeit für München?","answer":"Am angenehmsten ist es von Mai bis September für Biergärten und Sightseeing. Das Oktoberfest findet von Mitte September bis Anfang Oktober statt, und im Advent sorgen Christkindlmärkte für festliche Stimmung. Im Winter sind die nahen Alpen ein Plus."},{"question":"Wann ist das Oktoberfest in München?","answer":"Das Oktoberfest findet traditionell von Mitte September bis zum ersten Sonntag im Oktober auf der Theresienwiese statt und dauert rund 16 bis 18 Tage. Wer in dieser Zeit anreist, sollte Unterkünfte sehr früh buchen und für die Festzelte möglichst reservieren."},{"question":"Wie reist man am besten nach München an?","answer":"München ist per ICE aus ganz Deutschland sehr gut erreichbar, und der Hauptbahnhof liegt zentral. Auch die Anreise mit dem Auto ist möglich, und der Flughafen München ist über S-Bahn gut mit der Innenstadt verbunden."},{"question":"Braucht man in München ein Auto?","answer":"Nein, München hat einen hervorragenden Nahverkehr mit U-Bahn, S-Bahn, Tram und Bus (MVV), und die Innenstadt ist gut zu Fuß zu erkunden. Ein Auto ist eher hinderlich, lohnt sich aber für Ausflüge in die Alpen."},{"question":"Was sollte man am Marienplatz sehen?","answer":"Der Marienplatz ist das Herz Münchens mit dem prächtigen Neuen Rathaus und seinem Glockenspiel, der Mariensäule und dem Blick auf die Frauenkirche. Von der Aussichtsplattform des Alten Peter (St. Peter) hat man einen tollen Rundblick."},{"question":"Was macht die Münchner Biergartenkultur aus?","answer":"Biergärten gehören zur Münchner Lebensart. Unter Kastanien genießt man Maß, Brezn und bayerische Spezialitäten; an unbedienten Tischen darf oft eigenes Essen mitgebracht werden. Besonders bekannt sind die Gärten im Englischen Garten und am Viktualienmarkt."},{"question":"Welche Museen lohnen sich in München?","answer":"Sehenswert sind das Deutsche Museum als eines der größten Technikmuseen der Welt, die Pinakotheken mit bedeutender Kunst, das NS-Dokumentationszentrum sowie die BMW Welt und das BMW Museum für Autofans."},{"question":"Ist München für Familien geeignet?","answer":"Ja, sehr. Das Deutsche Museum, der Tierpark Hellabrunn, der Englische Garten, das Sea Life und Ausflüge an die Seen oder in die Alpen bieten viel Abwechslung für Kinder."},{"question":"Welche Tagesausflüge bieten sich von München an?","answer":"Beliebt sind das Schloss Neuschwanstein, die Zugspitze und Garmisch-Partenkirchen, die Seen wie Tegernsee und Starnberger See sowie ein Abstecher ins österreichische Salzburg. Vieles ist auch mit dem Bayern-Ticket per Bahn erreichbar."},{"question":"Wie viele Tage sollte man für München einplanen?","answer":"Für die wichtigsten Highlights der Stadt reichen 2 bis 3 Tage. Wer zusätzlich Museen vertiefen oder Tagesausflüge in die Alpen und zu den Schlössern unternehmen möchte, sollte mehr Zeit einplanen."}]$j$::jsonb, $t$München Städtereise: Marienplatz, Oktoberfest & beste Reisezeit$t$, $t$Dein München-Trip: der Marienplatz mit Glockenspiel, der Englische Garten, Biergärten, das Oktoberfest und royale Schlösser. Beste Reisezeit, Anreise, Highlights und Tipps im Überblick.$t$, $t$München Städtereise buchen, Hotel München, München Wochenende, Oktoberfest Reise, Neuschwanstein Tour ab München, Städtetrip Bayern$t$, false, $j$["nuernberg","salzburg","wien"]$j$::jsonb, ARRAY[$t$München$t$,$t$Bayern$t$,$t$Marienplatz$t$,$t$Neues Rathaus$t$,$t$Glockenspiel$t$,$t$Frauenkirche$t$,$t$Englischer Garten$t$,$t$Eisbach$t$,$t$Schloss Nymphenburg$t$,$t$Residenz München$t$,$t$Oktoberfest$t$,$t$Theresienwiese$t$,$t$Hofbräuhaus$t$,$t$Viktualienmarkt$t$,$t$Deutsches Museum$t$,$t$Neuschwanstein$t$]::text[], $t$München ist die Hauptstadt Bayerns und verbindet weltstädtisches Flair mit bayerischer Gemütlichkeit – mit dem Marienplatz und seinem Glockenspiel, der Frauenkirche, dem Englischen Garten samt Eisbach-Surfern, traditionsreichen Biergärten, royaler Pracht und dem weltberühmten Oktoberfest. Mit den Alpen und Schlössern wie Neuschwanstein vor der Haustür eignet sie sich ideal für einen Städtetrip und ist innerdeutsch sehr gut per ICE erreichbar. Die beste Reisezeit liegt zwischen Mai und September, das Oktoberfest findet von Mitte September bis Anfang Oktober statt.$t$, $t$München ist Bayerns charmante Hauptstadt mit Marienplatz, Biergärten, dem Englischen Garten, dem Oktoberfest und den Alpen vor der Haustür.$t$, $t$https://www.apearound.de/reiseziele/muenchen$t$, $t$/images/destinations/muenchen.jpg$t$, $t$/images/destinations/muenchen.jpg$t$, $t$München Städtereise: Marienplatz, Oktoberfest & beste Reisezeit$t$, $t$Dein München-Trip: der Marienplatz mit Glockenspiel, der Englische Garten, Biergärten, das Oktoberfest und royale Schlösser. Beste Reisezeit, Anreise, Highlights und Tipps im Überblick.$t$, $t$München Städtereise: Marienplatz, Oktoberfest & beste Reisezeit$t$, $t$Dein München-Trip: der Marienplatz mit Glockenspiel, der Englische Garten, Biergärten, das Oktoberfest und royale Schlösser. Beste Reisezeit, Anreise, Highlights und Tipps im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Neuseeland
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Neuseeland$t$, $t$neuseeland$t$, $t$Neuseeland$t$, $t$Ozeanien$t$, $t$Ozeanien$t$, $t$/images/destinations/neuseeland-hero.jpg$t$, $t$Atemberaubendes Naturparadies am anderen Ende der Welt mit Fjorden, Vulkanen, Gletschern, Geysiren, „Herr der Ringe“-Drehorten und Māori-Kultur.$t$, $t$Neuseeland gilt als eines der schönsten Länder der Erde und vereint auf zwei Hauptinseln eine unglaubliche landschaftliche Vielfalt. Die Südinsel beeindruckt mit den majestätischen Fjorden des Milford Sound, den Südalpen rund um den Aoraki/Mount Cook, dem türkisen Lake Tekapo unter sternenklarem Himmel sowie den Gletschern Franz Josef und Fox. Queenstown gilt als Abenteuer- und Adrenalinhauptstadt mit Bungeejumping und Skydiving. Die Nordinsel lockt mit der brodelnden Geothermie und Māori-Kultur in Rotorua, der spektakulären Wanderung Tongariro Alpine Crossing und natürlich Hobbiton, dem originalen Filmset aus „Der Herr der Ringe“. Dazu kommen einsame Strände, üppiger Regenwald und eine einzigartige Tierwelt mit dem Kiwi als Wahrzeichen. Wegen der Lage am anderen Ende der Welt und der vielen Höhepunkte lohnt sich eine längere Reise, am besten als Roadtrip oder mit dem Campervan. Neuseeland ist ideal für Natur-, Outdoor- und Abenteuerurlaube und besticht durch herzliche Gastfreundschaft.$t$, $t$Neuseeland ist ein atemberaubendes Naturparadies in Ozeanien mit Fjorden wie dem Milford Sound, den Südalpen, Gletschern, der Geothermie und Māori-Kultur in Rotorua sowie „Herr der Ringe“-Drehorten wie Hobbiton. Es eignet sich ideal für Roadtrips, Campervan- und Abenteuerreisen; für die Einreise sind eine NZeTA und die Touristenabgabe IVL nötig.$t$, $t$Da Neuseeland auf der Südhalbkugel liegt, sind die Jahreszeiten umgekehrt. Die beste Reisezeit ist der dortige Sommer und Herbst von November bis April mit mildem Wetter.$t$, $t$3 bis 4 Wochen$t$, ARRAY[$t$Rundreise$t$,$t$Roadtrip$t$,$t$Naturreise$t$,$t$Abenteuer$t$,$t$Wandern$t$,$t$Wohnmobilreise$t$,$t$Outdoor$t$]::text[], $j${"currency":"Neuseeland-Dollar (NZD)","language":"Englisch und Māori","flightTime":"ca. 24 Stunden und mehr ab Deutschland, immer mit Zwischenstopp(s) (Auckland)","timezone":"NZST (UTC+12), im Sommer NZDT (UTC+13); rund 11 bis 12 Stunden vor MEZ","visa":"Kein Visum für Touristen (bis 90 Tage); erforderlich sind die elektronische NZeTA-Reisegenehmigung sowie die Touristenabgabe IVL","bestMonths":"November bis April"}$j$::jsonb, $j$["Milford Sound – spektakulärer Fjord im Fiordland-Nationalpark (Südinsel)","Queenstown – Abenteuer- und Adrenalinhauptstadt mit Bungeejumping","Hobbiton – das originale Filmset aus „Der Herr der Ringe“ (Nordinsel)","Rotorua – Geothermie, Geysire und lebendige Māori-Kultur","Tongariro Alpine Crossing – eine der schönsten Tageswanderungen der Welt","Aoraki/Mount Cook und Lake Tekapo – Südalpen und Sternenhimmel","Franz-Josef- und Fox-Gletscher – Eis trifft auf Regenwald","Abel-Tasman-Nationalpark – goldene Strände und türkises Wasser"]$j$::jsonb, $j$["Eine Reise mit dem Campervan ist die klassische Art, Neuseeland zu erleben, und verbindet Mobilität mit naturnaher Übernachtung.","Die Distanzen sind durch kurvige Straßen länger als gedacht – planen Sie für Etappen großzügig Zeit ein und unterschätzen Sie die Fahrzeiten nicht.","Beim Lake Tekapo, einem international anerkannten Dark Sky Reserve, lohnt sich ein Blick in den außergewöhnlich klaren Sternenhimmel.","Die Māori-Kultur erlebt man am besten in Rotorua, etwa bei einem traditionellen Hangi-Essen und einer Haka-Vorführung."]$j$::jsonb, $j$[{"question":"Brauche ich für Neuseeland ein Visum?","answer":"Für touristische Aufenthalte bis zu 90 Tagen benötigen deutsche Staatsbürger kein Visum. Erforderlich sind jedoch die elektronische Reisegenehmigung NZeTA sowie die Touristenabgabe IVL, beide vor der Reise online zu beantragen bzw. zu zahlen."},{"question":"Was sind NZeTA und IVL?","answer":"Die NZeTA ist die elektronische Reisegenehmigung für Neuseeland, die IVL (International Visitor Conservation and Tourism Levy) eine Abgabe für Umwelt- und Tourismusprojekte. Beide werden in der Regel gemeinsam beantragt und sind für mehrere Einreisen über zwei Jahre gültig."},{"question":"Wann ist die beste Reisezeit für Neuseeland?","answer":"Da Neuseeland auf der Südhalbkugel liegt, sind die Jahreszeiten umgekehrt. Die beste Reisezeit ist der dortige Sommer und Herbst von November bis April. Der Dezember bis Februar ist Hauptsaison, der Herbst etwas ruhiger."},{"question":"Wie lange dauert der Flug nach Neuseeland?","answer":"Die Anreise dauert mit Zwischenstopps insgesamt rund 24 Stunden oder mehr, da es keine Direktflüge aus Deutschland gibt. Üblich sind ein oder zwei Stopps, etwa in Asien oder am Persischen Golf, mit Ziel Auckland."},{"question":"Welche Währung gilt in Neuseeland?","answer":"Gezahlt wird mit dem Neuseeland-Dollar (NZD). Kartenzahlung ist nahezu überall üblich, etwas Bargeld ist nur an wenigen abgelegenen Orten praktisch."},{"question":"Lohnt sich ein Mietwagen oder Campervan in Neuseeland?","answer":"Ja, ein Mietwagen oder Campervan ist nahezu unverzichtbar, um die Höhepunkte flexibel zu erreichen. Zu beachten ist der Linksverkehr sowie die teils kurvigen Straßen, die längere Fahrzeiten bedeuten."},{"question":"Sollte man beide Inseln besuchen?","answer":"Wenn es die Zeit erlaubt, ja. Die Nordinsel bietet Geothermie, Māori-Kultur und „Herr der Ringe“-Drehorte, die Südinsel dramatische Berge, Fjorde und Gletscher. Eine Fähre verbindet beide Inseln."},{"question":"Kann man in Neuseeland Drehorte aus „Der Herr der Ringe“ besuchen?","answer":"Ja, das ganze Land diente als Kulisse. Das bekannteste Ziel ist Hobbiton bei Matamata auf der Nordinsel, das originale Auenland-Filmset, das im Rahmen von Touren besichtigt werden kann."},{"question":"Ist Neuseeland für einen Familienurlaub geeignet?","answer":"Ja, Neuseeland ist sehr sicher und familienfreundlich. Naturerlebnisse, Tierbegegnungen, einfache Wanderungen, Strände und kindgerechte Abenteuer begeistern Familien. Wegen der langen Anreise lohnt sich ein längerer Aufenthalt."},{"question":"Erlebt man in Neuseeland die Māori-Kultur?","answer":"Ja, die Kultur der Māori, der indigenen Bevölkerung, ist lebendig und allgegenwärtig. Besonders in Rotorua kann man traditionelle Vorführungen, Kunst und ein Hangi-Essen erleben."},{"question":"Wie viele Tage sollte man für Neuseeland einplanen?","answer":"Wegen der weiten Anreise und der vielen Höhepunkte lohnen sich mindestens 3 Wochen. Wer beide Inseln in Ruhe erleben möchte, plant am besten 3 bis 4 Wochen ein."}]$j$::jsonb, $t$Neuseeland Urlaub: Milford Sound, Roadtrip & beste Reisezeit$t$, $t$Dein Neuseeland-Urlaub: der Milford Sound, Queenstown, Hobbiton, Rotorua und die Südalpen. Beste Reisezeit, Einreise mit NZeTA und IVL, Roadtrip-Tipps und Highlights im Überblick.$t$, $t$Neuseeland Reise buchen, Flug nach Auckland, Mietwagen oder Campervan Neuseeland, Rundreise Neuseeland, Roadtrip Südinsel, Hotel Queenstown$t$, true, $j$["australien","kanada","island"]$j$::jsonb, ARRAY[$t$Neuseeland$t$,$t$Milford Sound$t$,$t$Fiordland$t$,$t$Queenstown$t$,$t$Hobbiton$t$,$t$Rotorua$t$,$t$Tongariro Alpine Crossing$t$,$t$Aoraki/Mount Cook$t$,$t$Lake Tekapo$t$,$t$Franz-Josef-Gletscher$t$,$t$Abel-Tasman-Nationalpark$t$,$t$Auckland$t$,$t$Wellington$t$,$t$Māori$t$,$t$Neuseeland-Dollar$t$,$t$NZeTA$t$]::text[], $t$Neuseeland ist ein atemberaubendes Naturparadies in Ozeanien mit den Fjorden des Milford Sound, den Südalpen, Gletschern, der Geothermie und Māori-Kultur in Rotorua sowie „Herr der Ringe“-Drehorten wie Hobbiton. Wegen der Lage am anderen Ende der Welt und der vielen Höhepunkte lohnt sich eine längere Reise, am besten als Roadtrip oder mit dem Campervan. Die beste Reisezeit ist der dortige Sommer von November bis April; für die Einreise sind eine NZeTA und die Touristenabgabe IVL nötig.$t$, $t$Neuseeland ist ein Naturparadies mit Fjorden, Vulkanen, Gletschern, Māori-Kultur und „Herr der Ringe“-Drehorten; zur Einreise braucht man NZeTA und IVL.$t$, $t$https://www.apearound.de/reiseziele/neuseeland$t$, $t$/images/destinations/neuseeland.jpg$t$, $t$/images/destinations/neuseeland.jpg$t$, $t$Neuseeland Urlaub: Milford Sound, Roadtrip & beste Reisezeit$t$, $t$Dein Neuseeland-Urlaub: der Milford Sound, Queenstown, Hobbiton, Rotorua und die Südalpen. Beste Reisezeit, Einreise mit NZeTA und IVL, Roadtrip-Tipps und Highlights im Überblick.$t$, $t$Neuseeland Urlaub: Milford Sound, Roadtrip & beste Reisezeit$t$, $t$Dein Neuseeland-Urlaub: der Milford Sound, Queenstown, Hobbiton, Rotorua und die Südalpen. Beste Reisezeit, Einreise mit NZeTA und IVL, Roadtrip-Tipps und Highlights im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Norwegen
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Norwegen$t$, $t$norwegen$t$, $t$Norwegen$t$, $t$Skandinavien$t$, $t$Europa$t$, $t$/images/destinations/norwegen-hero.jpg$t$, $t$Spektakuläres Land der Fjorde mit tief eingeschnittenen Meeresarmen, schroffen Bergen, den Lofoten, Nordlichtern, Mitternachtssonne und atemberaubenden Roadtrips.$t$, $t$Norwegen ist ein Traumziel für Naturliebhaber und eines der landschaftlich spektakulärsten Länder Europas. Berühmt sind vor allem die Fjorde – tief eingeschnittene Meeresarme, die sich zwischen steile Felswände und Wasserfälle schmiegen. Der Geirangerfjord und der Nærøyfjord zählen zum UNESCO-Welterbe und gehören zu den schönsten der Welt. Die charmante Hansestadt Bergen mit dem bunten Hafenviertel Bryggen ist das Tor zu den Fjorden, während die Hauptstadt Oslo mit moderner Architektur, Museen und dem Vigeland-Park lockt. Im Norden begeistern die dramatischen Inseln der Lofoten mit roten Fischerhütten, im Winter tanzen über Tromsø die Nordlichter, und im Sommer geht im hohen Norden die Mitternachtssonne nicht unter. Wanderer zieht es auf spektakuläre Felsen wie den Preikestolen und die Trolltunga. Über die berühmten Norwegischen Landschaftsrouten und die Atlantikstraße führen unvergessliche Roadtrips, und das Postschiff Hurtigruten gleitet entlang der gesamten Küste. Norwegen ist ideal für Natur-, Roadtrip- und Abenteuerreisen.$t$, $t$Norwegen ist ein spektakuläres Naturland mit weltberühmten Fjorden wie dem Geirangerfjord, der Hansestadt Bergen, den dramatischen Lofoten, Nordlichtern im Winter und der Mitternachtssonne im Sommer. Es eignet sich ideal für Natur-, Roadtrip- und Abenteuerreisen, ist aber ein teures Reiseland.$t$, $t$Juni bis August für Fjorde, Wanderungen, Roadtrips und die Mitternachtssonne im Norden; November bis März für Nordlichter und Winterabenteuer rund um Tromsø.$t$, $t$1 bis 2 Wochen$t$, ARRAY[$t$Naturreise$t$,$t$Roadtrip$t$,$t$Rundreise$t$,$t$Wandern$t$,$t$Nordlichter$t$,$t$Kreuzfahrt$t$,$t$Abenteuer$t$]::text[], $j${"currency":"Norwegische Krone (NOK); Norwegen ist weitgehend bargeldlos","language":"Norwegisch; Englisch ist weit verbreitet","flightTime":"ca. 1,5 bis 2 Stunden ab Deutschland (Oslo)","timezone":"MEZ (UTC+1), identisch mit Deutschland","visa":"Kein Visum für EU-Bürger; Norwegen gehört zum Schengen-Raum, für die Einreise genügt der Personalausweis oder Reisepass","bestMonths":"Juni bis August; Nordlichter November bis März"}$j$::jsonb, $j$["Fjorde – der Geirangerfjord und der Nærøyfjord, UNESCO-Welterbe","Bergen – charmante Hansestadt mit dem bunten Hafenviertel Bryggen","Lofoten – dramatische Inseln mit roten Fischerhütten","Nordlichter – über Tromsø und Nordnorwegen im Winter","Mitternachtssonne – im Sommer im hohen Norden","Preikestolen und Trolltunga – spektakuläre Wanderungen zu berühmten Felsen","Oslo – Hauptstadt mit Oper, Museen und dem Vigeland-Park","Hurtigruten und Norwegische Landschaftsrouten – legendäre Reisewege"]$j$::jsonb, $j$["Norwegen ist sehr teuer – mit Selbstverpflegung, Einkäufen im Supermarkt und Übernachtungen in Hütten oder beim Camping lässt sich viel sparen; Alkohol gibt es nur im staatlichen Vinmonopolet.","Ein Fjord-Roadtrip lebt von den Fährverbindungen und den ausgeschilderten Norwegischen Landschaftsrouten – genügend Zeit für Stopps an Aussichtspunkten einplanen.","Berühmte Wanderungen wie Preikestolen oder Trolltunga erfordern gute Kondition, festes Schuhwerk und wetterfeste Kleidung; die Bedingungen können schnell umschlagen.","Dank des Jedermannsrechts darf man in der Natur fast überall zelten und wandern; für eine entspannte Variante bietet sich die Hurtigruten-Schiffsreise entlang der Küste an."]$j$::jsonb, $j$[{"question":"Brauche ich ein Visum für Norwegen?","answer":"Nein. Norwegen gehört zwar nicht zur EU, aber zum Schengen-Raum, daher benötigen EU-Bürger kein Visum. Für die Einreise genügt ein gültiger Personalausweis oder Reisepass."},{"question":"Wann ist die beste Reisezeit für Norwegen?","answer":"Für Fjorde, Wanderungen, Roadtrips und die Mitternachtssonne eignet sich der Sommer von Juni bis August. Wer Nordlichter erleben möchte, reist zwischen November und März in den Norden, etwa nach Tromsø."},{"question":"Welche Währung gilt in Norwegen?","answer":"Gezahlt wird mit der Norwegischen Krone (NOK), nicht mit dem Euro. Das Land ist weitgehend bargeldlos, sodass Kartenzahlung und kontaktloses Bezahlen praktisch überall möglich sind."},{"question":"Ist Norwegen ein teures Reiseland?","answer":"Ja, Norwegen gehört zu den teuersten Reiseländern Europas, besonders bei Restaurants, Alkohol und Unterkünften. Mit Selbstverpflegung, Camping und vorausschauender Planung lässt sich der Urlaub jedoch bezahlbarer gestalten."},{"question":"Lohnt sich ein Mietwagen in Norwegen?","answer":"Ja, sehr. Für die Erkundung der Fjorde, Berge und Küstenstraßen ist ein Mietwagen oder Wohnmobil ideal. Man sollte allerdings Fährverbindungen, Mautstrecken und längere Fahrzeiten durch kurvige Strecken einplanen."},{"question":"Wo und wann sieht man in Norwegen Nordlichter?","answer":"Die besten Chancen auf Polarlichter hat man von November bis März im Norden, etwa rund um Tromsø, in dunklen, klaren Nächten. Mehrere Übernachtungen erhöhen die Wahrscheinlichkeit deutlich."},{"question":"Was ist die Mitternachtssonne?","answer":"Nördlich des Polarkreises geht die Sonne im Hochsommer mehrere Wochen lang nicht unter. Diese Mitternachtssonne sorgt für taghelle Nächte und ist ein besonderes Erlebnis, etwa auf den Lofoten oder in Nordnorwegen."},{"question":"Welche Wanderungen sind in Norwegen besonders bekannt?","answer":"Zu den berühmtesten zählen der Preikestolen (Kanzelfelsen) über dem Lysefjord und die Trolltunga, ein spektakulär aufragender Felsvorsprung. Beide sind anspruchsvoll und erfordern gute Kondition sowie passende Ausrüstung."},{"question":"Spricht man in Norwegen Englisch?","answer":"Ja, Englisch ist sehr weit verbreitet und wird von fast allen gut gesprochen. Die Verständigung ist für deutsche Reisende daher unkompliziert."},{"question":"Wie viele Tage sollte man für Norwegen einplanen?","answer":"Für die Fjordregion rund um Bergen reicht eine knappe Woche. Wer zusätzlich die Lofoten oder den Norden erleben möchte, sollte wegen der großen Distanzen 10 bis 14 Tage oder mehr einplanen."}]$j$::jsonb, $t$Norwegen Urlaub: Fjorde, Lofoten, Nordlichter & beste Reisezeit$t$, $t$Dein Norwegen-Urlaub: die weltberühmten Fjorde, Bergen, die Lofoten, Nordlichter und die Mitternachtssonne. Beste Reisezeit, Roadtrip-Tipps, Highlights und praktische Hinweise im Überblick.$t$, $t$Norwegen Reise buchen, Flug nach Oslo oder Bergen, Mietwagen Norwegen, Fjord Rundreise, Hurtigruten Kreuzfahrt, Nordlichter Reise Tromsø, Hotel Bergen$t$, true, $j$["schweden","island","finnland"]$j$::jsonb, ARRAY[$t$Norwegen$t$,$t$Fjorde$t$,$t$Geirangerfjord$t$,$t$Nærøyfjord$t$,$t$Bergen$t$,$t$Bryggen$t$,$t$Lofoten$t$,$t$Tromsø$t$,$t$Nordlichter$t$,$t$Mitternachtssonne$t$,$t$Preikestolen$t$,$t$Trolltunga$t$,$t$Oslo$t$,$t$Hurtigruten$t$,$t$Atlantikstraße$t$,$t$Norwegische Krone$t$]::text[], $t$Norwegen ist ein spektakuläres Naturland mit weltberühmten Fjorden wie dem Geirangerfjord und Nærøyfjord, der Hansestadt Bergen, den dramatischen Inseln der Lofoten, Nordlichtern im Winter und der Mitternachtssonne im Sommer. Berühmte Wanderungen wie Preikestolen und Trolltunga sowie Roadtrips über die Norwegischen Landschaftsrouten machen es ideal für Natur-, Roadtrip- und Abenteuerreisen. Die beste Reisezeit ist der Sommer für die Fjorde und November bis März für Nordlichter; Norwegen ist allerdings ein teures Reiseland.$t$, $t$Norwegen ist das Land der Fjorde mit Bergen, den Lofoten, Nordlichtern und Mitternachtssonne – ideal für Natur- und Roadtrip-Reisen, am besten im Sommer.$t$, $t$https://www.apearound.de/reiseziele/norwegen$t$, $t$/images/destinations/norwegen.jpg$t$, $t$/images/destinations/norwegen.jpg$t$, $t$Norwegen Urlaub: Fjorde, Lofoten, Nordlichter & beste Reisezeit$t$, $t$Dein Norwegen-Urlaub: die weltberühmten Fjorde, Bergen, die Lofoten, Nordlichter und die Mitternachtssonne. Beste Reisezeit, Roadtrip-Tipps, Highlights und praktische Hinweise im Überblick.$t$, $t$Norwegen Urlaub: Fjorde, Lofoten, Nordlichter & beste Reisezeit$t$, $t$Dein Norwegen-Urlaub: die weltberühmten Fjorde, Bergen, die Lofoten, Nordlichter und die Mitternachtssonne. Beste Reisezeit, Roadtrip-Tipps, Highlights und praktische Hinweise im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Österreich
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Österreich$t$, $t$oesterreich$t$, $t$Österreich$t$, $t$Mitteleuropa$t$, $t$Europa$t$, $t$/images/destinations/oesterreich-hero.jpg$t$, $t$Alpennachbar mit kaiserlichem Wien, barockem Salzburg, malerischem Hallstatt, erstklassigen Skigebieten und traumhaften Bergseen – nah und vielseitig.$t$, $t$Österreich verbindet majestätische Alpenlandschaften mit kaiserlicher Kultur und ist für deutsche Reisende besonders schnell und unkompliziert erreichbar. Die Hauptstadt Wien begeistert mit dem Schloss Schönbrunn, dem Stephansdom, der Hofburg und ihrer weltberühmten Kaffeehauskultur. Salzburg verzaubert mit seiner barocken Altstadt, der Festung Hohensalzburg und dem Erbe Mozarts. Im Westen locken Tirol und die Alpen mit Innsbruck, erstklassigen Skigebieten wie Kitzbühel, Sölden und St. Anton sowie unzähligen Wanderrouten. Das Salzkammergut mit dem malerischen Hallstatt und glasklaren Bergseen ist im Sommer ein Traum, während die Wachau an der Donau mit Weinbergen und dem Stift Melk lockt. Die spektakuläre Großglockner-Hochalpenstraße führt durch alpine Hochgebirgswelt. Ob Städtetrip, Wintersport, Wandern, Wellness oder Familienurlaub – Österreich bietet das ganze Jahr über ein abwechslungsreiches und hochwertiges Reiseerlebnis.$t$, $t$Österreich ist ein vielseitiges Alpenland mit dem kaiserlichen Wien, dem barocken Salzburg, dem malerischen Hallstatt, erstklassigen Skigebieten in Tirol und traumhaften Bergseen im Salzkammergut. Es ist von Deutschland aus schnell erreichbar und eignet sich ganzjährig für Städtetrips, Wintersport, Wander- und Wellnessreisen.$t$, $t$Dezember bis März für Wintersport, Juni bis September für Wandern und Badeseen; die Städte Wien und Salzburg sind ganzjährig attraktiv.$t$, $t$Städtereise 3 bis 4 Tage, Aktiv- oder Skiurlaub rund eine Woche$t$, ARRAY[$t$Städtereise$t$,$t$Wintersport$t$,$t$Wandern$t$,$t$Naturreise$t$,$t$Wellness$t$,$t$Familien$t$,$t$Kulturreise$t$]::text[], $j${"currency":"Euro (EUR)","language":"Deutsch","flightTime":"ca. 1 bis 1,5 Stunden ab Deutschland (Wien); sehr gut mit Bahn oder Auto erreichbar","timezone":"MEZ (UTC+1), identisch mit Deutschland","visa":"Nicht erforderlich für EU-Bürger (Schengen-Raum)","bestMonths":"Dezember bis März (Wintersport) sowie Juni bis September (Sommer)"}$j$::jsonb, $j$["Wien – Schloss Schönbrunn, Stephansdom, Hofburg und Kaffeehauskultur","Salzburg – barocke Altstadt, Festung Hohensalzburg und Mozarts Erbe","Hallstatt – malerisches Dorf am See, UNESCO-Welterbe","Tirol und Innsbruck – Alpenpanorama, Wandern und Wintersport","Skigebiete – Kitzbühel, Sölden, St. Anton und Ischgl","Salzkammergut – glasklare Bergseen wie der Wolfgangsee","Großglockner-Hochalpenstraße – spektakuläre Panoramastraße durchs Hochgebirge","Wachau – Donautal mit Weinbergen und dem Stift Melk"]$j$::jsonb, $j$["Ein Besuch in einem traditionellen Wiener Kaffeehaus mit Melange und Sachertorte oder Apfelstrudel gehört zum Pflichtprogramm.","Das berühmte Hallstatt ist tagsüber stark überlaufen – am schönsten ist es früh am Morgen, am Abend oder in der Nebensaison.","Für die Nutzung der Autobahnen benötigt man eine Vignette, die als Klebe- oder digitale Variante erhältlich ist; einige Alpenstraßen sind zusätzlich mautpflichtig.","Im Sommer laden die Seen des Salzkammerguts zum Baden ein – das Wasser ist klar und an warmen Tagen angenehm erfrischend."]$j$::jsonb, $j$[{"question":"Wann ist die beste Reisezeit für Österreich?","answer":"Für Wintersport eignen sich die Monate Dezember bis März, für Wandern und Badeseen Juni bis September. Die Städte Wien und Salzburg sind ganzjährig attraktiv, im Advent zudem besonders stimmungsvoll."},{"question":"Welche Währung gilt in Österreich?","answer":"In Österreich zahlt man mit dem Euro (EUR). Kartenzahlung ist weit verbreitet, etwas Bargeld empfiehlt sich für kleinere Gasthäuser, Hütten und Märkte."},{"question":"Brauche ich eine Vignette für Österreich?","answer":"Ja, für die Nutzung der österreichischen Autobahnen und Schnellstraßen ist eine Vignette erforderlich, die als Klebevignette oder als digitale Vignette erhältlich ist. Einige Alpenstraßen und Tunnel sind zusätzlich gesondert mautpflichtig."},{"question":"Braucht man in Wien oder Salzburg ein Auto?","answer":"Nein, beide Städte verfügen über einen sehr guten öffentlichen Nahverkehr, und die Altstädte lassen sich gut zu Fuß erkunden. Für Touren in die Alpen oder ins Salzkammergut ist ein Auto dagegen praktisch."},{"question":"Welche Skigebiete sind in Österreich besonders bekannt?","answer":"Zu den bekanntesten zählen Kitzbühel, Sölden, St. Anton am Arlberg, Ischgl und Saalbach-Hinterglemm. Sie bieten zahlreiche Pistenkilometer, moderne Lifte und Après-Ski."},{"question":"Lohnt sich Hallstatt wirklich?","answer":"Ja, das Dorf am See zählt zu den fotogensten Orten Europas. Wegen des großen Andrangs empfiehlt sich ein Besuch früh am Morgen, am späten Nachmittag oder außerhalb der Hauptsaison."},{"question":"Ist Österreich für einen Familienurlaub geeignet?","answer":"Ja, Österreich ist sehr familienfreundlich. Im Winter gibt es kinderfreundliche Skischulen, im Sommer Badeseen, einfache Wanderungen, Almhütten und Erlebnisparks. Die kurzen Anreisewege sind ein zusätzlicher Vorteil."},{"question":"Wie kommt man am besten nach Österreich?","answer":"Österreich ist von Deutschland aus bequem mit dem Auto und der Bahn erreichbar, besonders aus dem Süden. Für entferntere Ziele bieten sich Flüge nach Wien, Salzburg oder Innsbruck an."},{"question":"Welche Spezialitäten sollte man in Österreich probieren?","answer":"Typisch sind Wiener Schnitzel, Tafelspitz, Kaiserschmarrn, Apfelstrudel und die Sachertorte. In den Bergregionen lohnen Käsespätzle und Kasnocken, dazu passen österreichische Weine aus der Wachau."},{"question":"Kann man im Sommer in Österreichs Seen baden?","answer":"Ja, besonders die Seen des Salzkammerguts wie der Wolfgangsee, der Attersee und der Wörthersee in Kärnten laden im Sommer zum Baden ein und haben oft sehr gute Wasserqualität."},{"question":"Wie viele Tage sollte man für Österreich einplanen?","answer":"Für eine Stadt wie Wien oder Salzburg reichen 3 bis 4 Tage. Für einen Ski- oder Wanderurlaub in den Alpen oder eine Rundreise sollte man rund eine Woche einplanen."}]$j$::jsonb, $t$Österreich Urlaub: Wien, Alpen, Reisetipps & beste Reisezeit$t$, $t$Dein Österreich-Urlaub: das kaiserliche Wien, barocke Salzburg, malerische Hallstatt, Top-Skigebiete in Tirol und Bergseen im Salzkammergut. Beste Reisezeit, Highlights und Reisetipps im Überblick.$t$, $t$Österreich Urlaub buchen, Hotel Wien oder Salzburg, Skiurlaub Tirol buchen, Ferienwohnung Alpen, Wanderurlaub Österreich, Städtereise Wien$t$, false, $j$["schweiz","slowenien","italien"]$j$::jsonb, ARRAY[$t$Österreich$t$,$t$Wien$t$,$t$Schloss Schönbrunn$t$,$t$Stephansdom$t$,$t$Salzburg$t$,$t$Festung Hohensalzburg$t$,$t$Mozart$t$,$t$Hallstatt$t$,$t$Tirol$t$,$t$Innsbruck$t$,$t$Kitzbühel$t$,$t$Salzkammergut$t$,$t$Wolfgangsee$t$,$t$Großglockner-Hochalpenstraße$t$,$t$Wachau$t$,$t$Wiener Schnitzel$t$]::text[], $t$Österreich ist ein vielseitiges Alpenland mit dem kaiserlichen Wien, dem barocken Salzburg, dem malerischen Hallstatt, erstklassigen Skigebieten in Tirol und traumhaften Bergseen im Salzkammergut. Das Land ist von Deutschland aus schnell mit Bahn oder Auto erreichbar und eignet sich ganzjährig für Städtetrips, Wintersport, Wander- und Wellnessreisen. Die beste Reisezeit ist Dezember bis März für Wintersport und Juni bis September für den Sommer.$t$, $t$Österreich ist ein vielseitiges Alpenland mit dem kaiserlichen Wien, barockem Salzburg, Hallstatt, Top-Skigebieten und traumhaften Bergseen.$t$, $t$https://www.apearound.de/reiseziele/oesterreich$t$, $t$/images/destinations/oesterreich.jpg$t$, $t$/images/destinations/oesterreich.jpg$t$, $t$Österreich Urlaub: Wien, Alpen, Reisetipps & beste Reisezeit$t$, $t$Dein Österreich-Urlaub: das kaiserliche Wien, barocke Salzburg, malerische Hallstatt, Top-Skigebiete in Tirol und Bergseen im Salzkammergut. Beste Reisezeit, Highlights und Reisetipps im Überblick.$t$, $t$Österreich Urlaub: Wien, Alpen, Reisetipps & beste Reisezeit$t$, $t$Dein Österreich-Urlaub: das kaiserliche Wien, barocke Salzburg, malerische Hallstatt, Top-Skigebiete in Tirol und Bergseen im Salzkammergut. Beste Reisezeit, Highlights und Reisetipps im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Paris
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Paris$t$, $t$paris$t$, $t$Frankreich$t$, $t$Île-de-France$t$, $t$Europa$t$, $t$/images/destinations/paris-hero.jpg$t$, $t$Die Stadt der Liebe mit Eiffelturm, Louvre, Notre-Dame, eleganten Boulevards, Kunst, Mode und unvergleichlichem savoir-vivre.$t$, $t$Paris ist eine der schönsten und romantischsten Städte der Welt und ein Klassiker für jeden Städtetrip. Das Wahrzeichen, der Eiffelturm, überragt die Stadt und ist abends bei der stündlichen Lichtshow besonders magisch. Im Louvre, dem größten Kunstmuseum der Welt, hängt die Mona Lisa, während das Musée d'Orsay die Meisterwerke der Impressionisten zeigt. Die wiedereröffnete Kathedrale Notre-Dame, die Prachtstraße Champs-Élysées mit dem Arc de Triomphe und das Künstlerviertel Montmartre mit der Basilika Sacré-Cœur gehören ebenso zum Pflichtprogramm wie eine Bootsfahrt auf der Seine. Vor den Toren der Stadt lockt das prunkvolle Schloss Versailles. Paris steht zudem für Genuss: Croissants und Macarons aus der Patisserie, Käse und Wein, kleine Bistros und die berühmte Café-Kultur. Mit seinem eleganten Flair, der Mode und Kunst an jeder Ecke ist Paris ideal für einen romantischen Kurztrip, eine Kultur- oder Familienreise – und von Deutschland aus schnell erreichbar.$t$, $t$Paris ist die romantische Hauptstadt Frankreichs mit Wahrzeichen wie dem Eiffelturm, dem Louvre, der wiedereröffneten Notre-Dame, den Champs-Élysées und Montmartre. Berühmt für Kunst, Mode und Genuss, eignet sich die gut erreichbare Metropole ideal für einen Städtetrip, eine Kultur- oder Familienreise.$t$, $t$April bis Juni sowie September und Oktober für mildes Wetter und blühende oder herbstliche Parks; im Dezember ist Paris weihnachtlich stimmungsvoll.$t$, $t$3 bis 4 Tage$t$, ARRAY[$t$Städtereise$t$,$t$Kulturreise$t$,$t$Kulinarik$t$,$t$Paare$t$,$t$Shopping$t$,$t$Familien$t$,$t$Wochenendtrip$t$]::text[], $j${"currency":"Euro (EUR)","language":"Französisch","flightTime":"ca. 1,5 Stunden ab Deutschland; auch bequem mit dem TGV-Hochgeschwindigkeitszug erreichbar","timezone":"MEZ (UTC+1), identisch mit Deutschland","visa":"Nicht erforderlich für EU-Bürger (Schengen-Raum)","bestMonths":"April bis Juni sowie September und Oktober"}$j$::jsonb, $j$["Eiffelturm – das Wahrzeichen mit Aussicht und abendlicher Lichtshow","Louvre – größtes Kunstmuseum der Welt mit der Mona Lisa","Notre-Dame – die wiedereröffnete gotische Kathedrale auf der Île de la Cité","Champs-Élysées und Arc de Triomphe – Prachtstraße und Triumphbogen","Montmartre und Sacré-Cœur – Künstlerviertel mit Blick über die Stadt","Seine – Bootsfahrt vorbei an den Sehenswürdigkeiten","Musée d'Orsay – Meisterwerke des Impressionismus","Schloss Versailles – prunkvolle Residenz vor den Toren der Stadt"]$j$::jsonb, $j$["Tickets für den Eiffelturm, den Louvre und die Katakomben sollte man unbedingt vorab online buchen, um lange Warteschlangen zu vermeiden.","Viele städtische Museen sind am ersten Sonntag im Monat kostenlos, und EU-Bürger unter 26 Jahren haben in vielen Häusern freien Eintritt.","Statt der teuren Lokale direkt an den Sehenswürdigkeiten lohnt sich ein Picknick mit Baguette, Käse und Wein auf dem Champ de Mars oder an der Seine.","Am besten bewegt man sich mit der Metro fort und erkundet die Viertel zu Fuß – ein Auto ist in Paris eher hinderlich."]$j$::jsonb, $j$[{"question":"Wann ist die beste Reisezeit für Paris?","answer":"Am angenehmsten sind April bis Juni sowie September und Oktober mit mildem Wetter und weniger Andrang. Paris ist aber ganzjährig reizvoll und im Dezember besonders festlich geschmückt."},{"question":"Wie viele Tage sollte man für Paris einplanen?","answer":"Für die wichtigsten Sehenswürdigkeiten sind 3 bis 4 Tage ideal. Wer zusätzlich Versailles, das Disneyland oder mehr Museen besuchen möchte, kann problemlos länger bleiben."},{"question":"Braucht man in Paris ein Auto?","answer":"Nein, Paris verfügt über ein dichtes Metro- und Busnetz, und viele Viertel lassen sich gut zu Fuß erkunden. Ein Auto ist wegen Verkehr, Parkplatznot und Umweltzonen eher hinderlich."},{"question":"Wie bewegt man sich am besten in Paris fort?","answer":"Das beste Verkehrsmittel ist die Metro, ergänzt durch Busse und die RER für Ausflüge ins Umland. Für längere Aufenthalte lohnt sich eine aufladbare Verkehrskarte oder ein Tagesticket."},{"question":"Kann man Notre-Dame wieder besichtigen?","answer":"Ja, die Kathedrale Notre-Dame wurde nach den umfangreichen Restaurierungsarbeiten infolge des Brandes Ende 2024 wiedereröffnet und kann erneut besichtigt werden. In Stoßzeiten muss man mit Wartezeiten rechnen."},{"question":"Sollte man Tickets für den Eiffelturm und den Louvre vorab buchen?","answer":"Unbedingt. Für den Eiffelturm, den Louvre und weitere beliebte Attraktionen empfiehlt sich die Online-Buchung mit fester Zeitfensterwahl, da die Schlangen vor Ort sehr lang sein können."},{"question":"Lohnt sich ein Tagesausflug nach Versailles?","answer":"Ja, das prunkvolle Schloss Versailles mit seinen weitläufigen Gärten ist ein lohnender Tagesausflug und mit der RER in etwa einer Stunde erreichbar. Auch hier sollte man Tickets vorab buchen."},{"question":"Ist Paris für einen Familienurlaub geeignet?","answer":"Ja, Paris bietet viel für Familien: das Disneyland Paris vor den Toren der Stadt, Bootsfahrten auf der Seine, Parks, den Tierpark sowie kindgerechte Museen und den Eiffelturm."},{"question":"Welche Spezialitäten sollte man in Paris probieren?","answer":"Typisch sind frische Croissants und Pain au Chocolat, Macarons, Käse und Wein, Crêpes, klassische Bistro-Gerichte wie Steak Frites sowie ein Café au Lait in einem typischen Pariser Café."},{"question":"Ist Paris sicher für Reisende?","answer":"Paris ist insgesamt ein sicheres Reiseziel. Wie in vielen Großstädten sollte man jedoch besonders in der Metro, an Bahnhöfen und an Touristenhotspots auf Taschendiebe achten."},{"question":"Wie kommt man am besten nach Paris?","answer":"Am schnellsten reist man per Flug (rund 1,5 Stunden ab Deutschland) oder bequem mit dem TGV-Hochgeschwindigkeitszug. Vom Flughafen gelangt man mit der RER oder Bussen ins Zentrum."}]$j$::jsonb, $t$Paris Städtereise: Eiffelturm, Louvre, Tipps & beste Reisezeit$t$, $t$Deine Paris-Reise: Eiffelturm, Louvre, die wiedereröffnete Notre-Dame, Montmartre und Versailles. Beste Reisezeit, Sehenswürdigkeiten, Insidertipps und praktische Infos im Überblick.$t$, $t$Paris Städtereise buchen, Hotel Paris, Flug nach Paris, Eiffelturm Tickets, Louvre Tickets, Wochenendtrip Paris, Disneyland Paris$t$, false, $j$["london","rom","wien"]$j$::jsonb, ARRAY[$t$Paris$t$,$t$Eiffelturm$t$,$t$Louvre$t$,$t$Mona Lisa$t$,$t$Notre-Dame$t$,$t$Champs-Élysées$t$,$t$Arc de Triomphe$t$,$t$Montmartre$t$,$t$Sacré-Cœur$t$,$t$Seine$t$,$t$Musée d'Orsay$t$,$t$Versailles$t$,$t$Île de la Cité$t$,$t$Disneyland Paris$t$,$t$Île-de-France$t$]::text[], $t$Paris ist die romantische Hauptstadt Frankreichs mit weltberühmten Wahrzeichen wie dem Eiffelturm, dem Louvre mit der Mona Lisa, der wiedereröffneten Kathedrale Notre-Dame, den Champs-Élysées und dem Künstlerviertel Montmartre. Berühmt für Kunst, Mode und Genuss, eignet sich die gut erreichbare Metropole ideal für einen romantischen Städtetrip sowie Kultur- und Familienreisen. Die beste Reisezeit liegt im Frühling und Frühherbst.$t$, $t$Paris ist die Stadt der Liebe mit Eiffelturm, Louvre, der wiedereröffneten Notre-Dame, Montmartre und Versailles – ideal für einen Städtetrip von 3 bis 4 Tagen.$t$, $t$https://www.apearound.de/reiseziele/paris$t$, $t$/images/destinations/paris.jpg$t$, $t$/images/destinations/paris.jpg$t$, $t$Paris Städtereise: Eiffelturm, Louvre, Tipps & beste Reisezeit$t$, $t$Deine Paris-Reise: Eiffelturm, Louvre, die wiedereröffnete Notre-Dame, Montmartre und Versailles. Beste Reisezeit, Sehenswürdigkeiten, Insidertipps und praktische Infos im Überblick.$t$, $t$Paris Städtereise: Eiffelturm, Louvre, Tipps & beste Reisezeit$t$, $t$Deine Paris-Reise: Eiffelturm, Louvre, die wiedereröffnete Notre-Dame, Montmartre und Versailles. Beste Reisezeit, Sehenswürdigkeiten, Insidertipps und praktische Infos im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Philippinen
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Philippinen$t$, $t$philippinen$t$, $t$Philippinen$t$, $t$Südostasien$t$, $t$Asien$t$, $t$/images/destinations/philippinen-hero.jpg$t$, $t$Tropisches Inselparadies aus über 7.000 Inseln mit traumhaften Lagunen, weißen Stränden, erstklassigem Tauchen und herzlicher, englischsprachiger Gastfreundschaft.$t$, $t$Die Philippinen sind ein gewaltiges Archipel aus über 7.000 Inseln und eines der schönsten Strand- und Tauchparadiese der Welt. Im Mittelpunkt steht Palawan mit den spektakulären Lagunen und Kalksteinfelsen von El Nido und Coron, die per Inselhüpfen erkundet werden, sowie dem unterirdischen Fluss von Puerto Princesa. Boracay lockt mit seinem berühmten White Beach, während Bohol mit den kuriosen Chocolate Hills und den winzigen Koboldmakis (Tarsier) überrascht. Surfer zieht es nach Siargao, Kulturreisende zu den jahrtausendealten Reisterrassen von Banaue und Batad auf Luzon. Unter Wasser warten Korallenriffe, Schiffswracks und sanfte Walhaie. Die Philippinen punkten zudem mit einer Besonderheit: Englisch ist Amtssprache und nahezu überall verständlich, und die Menschen gelten als außergewöhnlich herzlich und fröhlich. Ideal für Strandurlaub, Inselhüpfen, Tauchen und Abenteuer.$t$, $t$Die Philippinen sind ein tropisches Archipel aus über 7.000 Inseln mit traumhaften Lagunen und Stränden in Palawan (El Nido, Coron), Boracay, den Chocolate Hills auf Bohol und erstklassigen Tauchgründen. Englisch ist weit verbreitet, die Menschen sind sehr gastfreundlich, und das Land eignet sich ideal für Strandurlaub, Inselhüpfen, Tauchen und Abenteuer.$t$, $t$Die beste Reisezeit ist die Trockenzeit von Dezember bis Mai. Von Juni bis November ist Regen- und Taifunsaison mit höherem Risiko für Stürme.$t$, $t$2 bis 3 Wochen$t$, ARRAY[$t$Strandurlaub$t$,$t$Inselhüpfen$t$,$t$Tauchen$t$,$t$Naturreise$t$,$t$Backpacking$t$,$t$Abenteuer$t$,$t$Schnorcheln$t$]::text[], $j${"currency":"Philippinischer Peso (PHP)","language":"Filipino (Tagalog) und Englisch; Englisch ist weit verbreitet","flightTime":"ca. 15 bis 17 Stunden mit Zwischenstopp (Manila, Cebu)","timezone":"PHT (UTC+8), sieben Stunden vor MEZ","visa":"Visumfreier Aufenthalt bis 30 Tage (verlängerbar); vor der Einreise ist die eTravel-Registrierung online auszufüllen","bestMonths":"Dezember bis Mai"}$j$::jsonb, $j$["El Nido und Coron (Palawan) – traumhafte Lagunen, Kalksteinfelsen und Inselhüpfen","Puerto Princesa Underground River – unterirdischer Fluss und UNESCO-Welterbe","Boracay – der berühmte White Beach mit feinstem Sand","Bohol – die kuriosen Chocolate Hills und die winzigen Tarsier","Siargao – Surferparadies mit dem Spot Cloud 9","Reisterrassen von Banaue und Batad – jahrtausendealte Kulturlandschaft auf Luzon","Walhaie in Donsol – respektvolles Schwimmen mit den sanften Riesen","Apo Reef und Cebu – erstklassige Tauch- und Schnorchelgründe"]$j$::jsonb, $j$["Die Lagunen von El Nido und Coron erkundet man am schönsten bei einer Inselhüpf-Tour; wer Menschenmassen meiden will, startet früh oder wählt private Touren.","Da die Inseln per Inlandsflug und Fähre verbunden sind, sollte man bei der Planung großzügige Puffer einplanen, falls sich Verbindungen verspäten oder ausfallen.","Walhaie erlebt man am verträglichsten im freien Schwimmen vor Donsol, statt an Orten mit Anfütterung wie Oslob.","Englisch wird fast überall gesprochen, was Reisen, Verhandeln und Verständigung auf den Philippinen besonders einfach macht."]$j$::jsonb, $j$[{"question":"Brauche ich ein Visum für die Philippinen?","answer":"Deutsche Staatsbürger können für touristische Aufenthalte bis zu 30 Tage visumfrei einreisen; eine Verlängerung vor Ort ist möglich. Zusätzlich ist vor der Einreise die kostenlose eTravel-Registrierung online auszufüllen. Der Reisepass muss noch mindestens sechs Monate gültig sein."},{"question":"Wann ist die beste Reisezeit für die Philippinen?","answer":"Ideal ist die Trockenzeit von Dezember bis Mai. Von Juni bis November ist Regen- und Taifunsaison; in dieser Zeit können Stürme einzelne Regionen und Flugverbindungen beeinträchtigen."},{"question":"Welche Währung gilt auf den Philippinen?","answer":"Gezahlt wird mit dem Philippinischen Peso (PHP). In Städten und Resorts ist Kartenzahlung möglich, auf kleineren Inseln und an Märkten ist jedoch Bargeld unerlässlich. Geldautomaten gibt es nicht überall, daher vorab abheben."},{"question":"Wie reist man zwischen den Inseln?","answer":"Die wichtigsten Verkehrsmittel sind Inlandsflüge und Fähren. Vor Ort bewegt man sich mit Tricycles, Jeepneys und Vans fort. Ein eigener Mietwagen ist auf einem Inselstaat dieser Art unüblich und selten nötig."},{"question":"Spricht man auf den Philippinen Englisch?","answer":"Ja, Englisch ist Amtssprache und nahezu überall verständlich. Das macht die Philippinen für deutsche Reisende besonders unkompliziert in Bezug auf Verständigung und Organisation."},{"question":"Kann man auf den Philippinen das Leitungswasser trinken?","answer":"Nein, das Leitungswasser ist nicht zum Trinken geeignet. Man sollte abgefülltes Wasser verwenden und bei Eiswürfeln sowie rohen Speisen vorsichtig sein."},{"question":"Welche Impfungen werden für die Philippinen empfohlen?","answer":"Vorgeschrieben sind in der Regel keine Impfungen. Empfohlen werden Standardimpfungen sowie je nach Reiseart Hepatitis A und teils Typhus. Für eine individuelle Beratung sollte man rechtzeitig ein Tropeninstitut oder den Hausarzt aufsuchen."},{"question":"Sind die Philippinen sicher für Reisende?","answer":"Die klassischen Tourismusregionen wie Palawan, Bohol, Cebu und Siargao gelten als gut bereisbar. Von einzelnen Gebieten im Süden des Landes wird jedoch abgeraten. Vor der Reise sollte man die aktuellen Hinweise des Auswärtigen Amts prüfen."},{"question":"Sind die Philippinen für einen Familienurlaub geeignet?","answer":"Ja, ruhige Strände, Schnorcheln, Tiererlebnisse und die herzliche, englischsprachige Gastfreundschaft eignen sich gut für Familien. Wegen der Inseldistanzen und Anreise sollte man jedoch etwas mehr Reisezeit einplanen."},{"question":"Welche Gerichte sollte man auf den Philippinen probieren?","answer":"Typisch sind Adobo (in Essig und Sojasauce geschmortes Fleisch), Sinigang (saure Suppe), Lechon (Spanferkel), frischer Fisch und die süße Nachspeise Halo-Halo. Tropische Früchte wie Mango sind ein Genuss."},{"question":"Wie viele Tage sollte man für die Philippinen einplanen?","answer":"Für ein bis zwei Inselregionen wie Palawan und Bohol sind etwa 10 bis 14 Tage sinnvoll. Wer mehrere Inseln und Aktivitäten wie Tauchen und Surfen verbinden möchte, plant am besten 2 bis 3 Wochen ein."}]$j$::jsonb, $t$Philippinen Urlaub: Palawan, Inselhüpfen, Tipps & beste Reisezeit$t$, $t$Dein Philippinen-Urlaub: die Lagunen von El Nido und Coron, Boracay, die Chocolate Hills auf Bohol und Top-Tauchgründe. Beste Reisezeit, Visum, Highlights und Reisetipps im Überblick.$t$, $t$Philippinen Reise buchen, Flug nach Manila oder Cebu, Hotel Palawan oder Boracay, Inselhüpfen El Nido, Tauchreise Philippinen, Backpacking Südostasien$t$, false, $j$["indonesien","thailand","malaysia"]$j$::jsonb, ARRAY[$t$Philippinen$t$,$t$Palawan$t$,$t$El Nido$t$,$t$Coron$t$,$t$Puerto Princesa$t$,$t$Boracay$t$,$t$Bohol$t$,$t$Chocolate Hills$t$,$t$Tarsier$t$,$t$Siargao$t$,$t$Banaue$t$,$t$Batad$t$,$t$Cebu$t$,$t$Walhaie$t$,$t$Philippinischer Peso$t$,$t$Adobo$t$]::text[], $t$Die Philippinen sind ein tropisches Archipel aus über 7.000 Inseln, bekannt für die traumhaften Lagunen von El Nido und Coron auf Palawan, den White Beach von Boracay, die Chocolate Hills auf Bohol und erstklassige Tauchgründe. Englisch ist Amtssprache und weit verbreitet, die Menschen gelten als besonders herzlich, und das Land eignet sich ideal für Strandurlaub, Inselhüpfen, Tauchen und Abenteuer. Die beste Reisezeit ist die Trockenzeit von Dezember bis Mai.$t$, $t$Die Philippinen sind ein tropisches Archipel mit über 7.000 Inseln, traumhaften Lagunen in Palawan, Boracay und Top-Tauchgründen, am besten von Dezember bis Mai.$t$, $t$https://www.apearound.de/reiseziele/philippinen$t$, $t$/images/destinations/philippinen.jpg$t$, $t$/images/destinations/philippinen.jpg$t$, $t$Philippinen Urlaub: Palawan, Inselhüpfen, Tipps & beste Reisezeit$t$, $t$Dein Philippinen-Urlaub: die Lagunen von El Nido und Coron, Boracay, die Chocolate Hills auf Bohol und Top-Tauchgründe. Beste Reisezeit, Visum, Highlights und Reisetipps im Überblick.$t$, $t$Philippinen Urlaub: Palawan, Inselhüpfen, Tipps & beste Reisezeit$t$, $t$Dein Philippinen-Urlaub: die Lagunen von El Nido und Coron, Boracay, die Chocolate Hills auf Bohol und Top-Tauchgründe. Beste Reisezeit, Visum, Highlights und Reisetipps im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Polen
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Polen$t$, $t$polen$t$, $t$Polen$t$, $t$Mitteleuropa$t$, $t$Europa$t$, $t$/images/destinations/polen-hero.jpg$t$, $t$Vielfältiges Reiseland mit prachtvollen Altstädten, bewegter Geschichte, Ostseeküste, Seenplatten und gutem Preis-Leistungs-Verhältnis.$t$, $t$Polen ist ein überraschend vielseitiges Reiseland im Herzen Europas und für Deutsche besonders schnell und günstig erreichbar. Lebendige Städte wie das königliche Krakau mit seiner mittelalterlichen Altstadt und dem Wawelschloss, die wiederaufgebaute Hauptstadt Warschau oder das hanseatisch geprägte Danzig verbinden reiche Geschichte mit moderner Kultur und Gastronomie. Daneben locken großartige Naturräume: die endlosen Sandstrände der Ostseeküste, die idyllische Seenlandschaft der Masuren, die schroffen Gipfel der Tatra rund um Zakopane sowie der urtümliche Białowieża-Urwald mit seinen Wisenten. Geschichtsorte wie die Gedenkstätte Auschwitz-Birkenau machen Polen zugleich zu einem Ziel der Erinnerung. Wer Städtereise, Natur, Strand und Kulinarik bei moderaten Preisen sucht, findet in Polen eine ideale Kombination.$t$, $t$Polen ist ein vielfältiges mitteleuropäisches Reiseland mit historischen Städten wie Krakau, Warschau und Danzig, der Ostseeküste, den Masuren und dem Tatra-Gebirge. Es ist von Deutschland aus schnell erreichbar, bietet ein gutes Preis-Leistungs-Verhältnis und eignet sich für Städtereisen, Natur- und Aktivurlaube.$t$, $t$Mai bis September für Städte, Küste und Seen; das Tatra-Gebirge ist im Winter (Dezember bis März) zum Skifahren attraktiv.$t$, $t$Städtereise 3 bis 4 Tage, Rundreise 7 bis 10 Tage$t$, ARRAY[$t$Städtereise$t$,$t$Kulturreise$t$,$t$Naturreise$t$,$t$Strandurlaub$t$,$t$Aktivurlaub$t$,$t$Familien$t$,$t$Geschichtsreise$t$]::text[], $j${"currency":"Polnischer Złoty (PLN)","language":"Polnisch","flightTime":"ca. 1 bis 2 Stunden ab Deutschland; auch gut mit Bahn oder Auto erreichbar","timezone":"MEZ (UTC+1), identisch mit Deutschland","visa":"Nicht erforderlich für EU-Bürger (Schengen-Raum)","bestMonths":"Mai bis September, Wintersport Dezember bis März"}$j$::jsonb, $j$["Krakau – mittelalterliche Altstadt, Marktplatz und das Wawelschloss","Warschau – wiederaufgebaute Altstadt, Königsschloss und moderne Skyline","Danzig (Gdańsk) – hanseatische Prachtbauten am Wasser und Tor zur Ostsee","Gedenkstätte Auschwitz-Birkenau – bedeutender Erinnerungsort der Geschichte","Masuren – idyllische Seenplatte zum Segeln, Kanufahren und Entspannen","Salzbergwerk Wieliczka – unterirdische Kammern und Kapellen aus Salz","Tatra-Gebirge und Zakopane – Wandern, Skifahren und urige Bergkultur","Białowieża-Urwald – uralter Wald und Heimat freilebender Wisente"]$j$::jsonb, $j$["In den Milchbars (bar mleczny) gibt es traditionelle polnische Gerichte wie Pierogi sehr günstig und authentisch.","Die Ostseebäder Sopot und Hel sind im Sommer ein schöner, oft unterschätzter Strandtipp abseits der bekannten Mittelmeerziele.","Wer Krakau besucht, sollte einen Abstecher ins ehemalige jüdische Viertel Kazimierz mit seinen Cafés und seiner lebendigen Atmosphäre einplanen.","Der Hochsommer in den Masuren lässt sich am entspanntesten vom Wasser aus erleben – Hausboote und Kanus lassen sich vielerorts mieten."]$j$::jsonb, $j$[{"question":"Wann ist die beste Reisezeit für Polen?","answer":"Für Städtereisen, die Ostseeküste und die Masuren eignen sich die Monate Mai bis September am besten. Wer Wintersport in der Tatra plant, reist zwischen Dezember und März. Frühjahr und Herbst sind ideal für Städtetrips mit weniger Andrang."},{"question":"Welche Währung gilt in Polen?","answer":"In Polen zahlt man mit dem Polnischen Złoty (PLN), nicht mit dem Euro. Kartenzahlung ist nahezu überall möglich, etwas Bargeld empfiehlt sich für Märkte und kleine Lokale."},{"question":"Brauche ich ein Visum für Polen?","answer":"Nein. Polen ist EU- und Schengen-Mitglied, daher benötigen EU-Bürger kein Visum. Für die Einreise genügt ein gültiger Personalausweis oder Reisepass."},{"question":"Wie komme ich am besten nach Polen?","answer":"Polen ist von Deutschland aus sehr schnell erreichbar: per Flug nach Warschau oder Krakau in 1 bis 2 Stunden, bequem mit der Bahn oder einfach mit dem eigenen Auto, da viele Ziele wie Breslau oder Stettin grenznah liegen."},{"question":"Spricht man in Polen Englisch?","answer":"In Städten und touristischen Regionen sprechen vor allem jüngere Menschen gut Englisch. Auf dem Land sind Grundkenntnisse seltener – ein paar polnische Höflichkeitsfloskeln werden dort sehr geschätzt."},{"question":"Ist Polen ein günstiges Reiseland?","answer":"Ja, im Vergleich zu Deutschland sind Essen, Unterkünfte und Nahverkehr in Polen meist deutlich preiswerter, was es zu einem attraktiven Ziel mit gutem Preis-Leistungs-Verhältnis macht."},{"question":"Lohnt sich ein Mietwagen in Polen?","answer":"Für Städtereisen ist ein Mietwagen meist nicht nötig, da der öffentliche Nahverkehr gut ist. Für Rundreisen oder die Erkundung von Masuren, Tatra und Küste ist ein Auto jedoch sehr praktisch und sorgt für mehr Flexibilität."},{"question":"Welche Städte in Polen sollte man besuchen?","answer":"Zu den lohnendsten Städten zählen Krakau mit seiner historischen Altstadt, die Hauptstadt Warschau, das maritime Danzig, das charmante Breslau (Wrocław) mit seinen Brücken sowie Posen (Poznań)."},{"question":"Ist Polen für einen Familienurlaub geeignet?","answer":"Ja, Polen bietet familienfreundliche Ostseestrände, Seenlandschaften zum Baden und Paddeln, Freizeitparks sowie kindgerechte Städte mit Burgen und Museen. Die kurzen Anreisewege machen es besonders praktisch."},{"question":"Welche typischen Gerichte sollte man in Polen probieren?","answer":"Klassiker sind Pierogi (gefüllte Teigtaschen), Bigos (Sauerkrauteintopf), Żurek (Sauerteigsuppe), Placki ziemniaczane (Kartoffelpuffer) und süße Pączki (Krapfen). Probieren lässt sich das alles günstig in einer Milchbar."},{"question":"Ist Polen ein sicheres Reiseland?","answer":"Ja, Polen gilt als sicheres Reiseland mit niedriger Kriminalität in touristischen Gebieten. Wie überall sollte man in vollen Städten und an Bahnhöfen auf Taschendiebe achten."},{"question":"Wie viele Tage sollte man für Polen einplanen?","answer":"Für eine einzelne Stadt wie Krakau oder Danzig reichen 3 bis 4 Tage. Für eine Rundreise mit mehreren Städten oder Naturregionen sollte man 7 bis 10 Tage einplanen."}]$j$::jsonb, $t$Polen Urlaub: Reisetipps, Städte, Sehenswürdigkeiten & beste Reisezeit$t$, $t$Dein Polen-Urlaub: von Krakau, Warschau und Danzig über die Ostseeküste bis zu Masuren und Tatra. Beste Reisezeit, Highlights und praktische Reisetipps im Überblick.$t$, $t$Städtereise Polen buchen, Flug und Hotel Krakau oder Warschau, Mietwagen Polen vergleichen, Ostsee Polen Unterkunft, Ausflüge und Stadtführungen Polen$t$, true, $j$["tschechien","ungarn","slowakei"]$j$::jsonb, ARRAY[$t$Polen$t$,$t$Krakau$t$,$t$Warschau$t$,$t$Danzig$t$,$t$Breslau$t$,$t$Posen$t$,$t$Masuren$t$,$t$Tatra-Gebirge$t$,$t$Zakopane$t$,$t$Ostseeküste$t$,$t$Auschwitz-Birkenau$t$,$t$Wawelschloss$t$,$t$Salzbergwerk Wieliczka$t$,$t$Białowieża-Urwald$t$,$t$Złoty$t$,$t$Pierogi$t$]::text[], $t$Polen ist ein vielseitiges Reiseland in Mitteleuropa mit historischen Städten wie Krakau, Warschau und Danzig, der Ostseeküste, der Seenplatte Masuren und dem Tatra-Gebirge. Es ist von Deutschland aus schnell und günstig erreichbar und bietet ein sehr gutes Preis-Leistungs-Verhältnis. Polen eignet sich für Städtereisen, Kultur-, Natur- und Strandurlaube gleichermaßen.$t$, $t$Polen ist ein vielseitiges mitteleuropäisches Reiseland mit historischen Städten, Ostseeküste, Seen und Bergen – schnell erreichbar und preiswert.$t$, $t$https://www.apearound.de/reiseziele/polen$t$, $t$/images/destinations/polen.jpg$t$, $t$/images/destinations/polen.jpg$t$, $t$Polen Urlaub: Reisetipps, Städte, Sehenswürdigkeiten & beste Reisezeit$t$, $t$Dein Polen-Urlaub: von Krakau, Warschau und Danzig über die Ostseeküste bis zu Masuren und Tatra. Beste Reisezeit, Highlights und praktische Reisetipps im Überblick.$t$, $t$Polen Urlaub: Reisetipps, Städte, Sehenswürdigkeiten & beste Reisezeit$t$, $t$Dein Polen-Urlaub: von Krakau, Warschau und Danzig über die Ostseeküste bis zu Masuren und Tatra. Beste Reisezeit, Highlights und praktische Reisetipps im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Portugal
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Portugal$t$, $t$portugal$t$, $t$Portugal$t$, $t$Südwesteuropa (Iberische Halbinsel)$t$, $t$Europa$t$, $t$/images/destinations/portugal-hero.jpg$t$, $t$Sonniges Land am Atlantik mit dem charmanten Lissabon, dem Portwein-Porto, den Traumstränden der Algarve, Märchenschlössern in Sintra und Fado-Melancholie.$t$, $t$Portugal begeistert mit einer Mischung aus Atlantikküste, lebendigen Städten, reicher Geschichte und herzlicher Gastfreundschaft – und das zu meist moderaten Preisen. Die Hauptstadt Lissabon verzaubert mit dem historischen Viertel Alfama, der nostalgischen Straßenbahn 28, dem Belém-Turm und den berühmten Pastéis de Nata. Im Norden lockt Porto mit der malerischen Ribeira, der Dom-Luís-Brücke und den Portweinkellern von Vila Nova de Gaia. Die Algarve im Süden ist ein Paradies aus goldenen Stränden, bizarren Felsbuchten und Grotten wie der Benagil-Höhle. Bei Lissabon liegen die Märchenschlösser von Sintra, allen voran der bunte Pena-Palast. Weinliebhaber zieht es ins terrassierte Douro-Tal, Surfer an Spots wie Ericeira oder zu den Riesenwellen von Nazaré. Auch die Atlantikinseln Madeira und die Azoren mit ihrer üppigen Natur sind beliebte Ziele. Dazu kommen die melancholischen Klänge des Fado und eine exzellente Küche mit frischem Fisch. Portugal ist ideal für Strand-, Städte-, Roadtrip- und Genussreisen.$t$, $t$Portugal ist ein sonniges Land am Atlantik mit dem charmanten Lissabon, dem Portwein-Porto, den Traumstränden der Algarve, den Märchenschlössern von Sintra und den Atlantikinseln Madeira und Azoren. Bekannt für Fado, gute Küche und moderate Preise, eignet es sich ideal für Strand-, Städte-, Roadtrip- und Genussreisen.$t$, $t$April bis Oktober ist allgemein ideal; die Algarve und die Strände sind im Sommer am schönsten, während Frühling und Herbst angenehm mild und weniger überlaufen für Städtereisen und Rundreisen sind.$t$, $t$1 bis 2 Wochen$t$, ARRAY[$t$Strandurlaub$t$,$t$Städtereise$t$,$t$Roadtrip$t$,$t$Rundreise$t$,$t$Kulinarik$t$,$t$Surfen$t$,$t$Kulturreise$t$]::text[], $j${"currency":"Euro (EUR)","language":"Portugiesisch; in touristischen Orten oft auch Englisch","flightTime":"ca. 3 bis 3,5 Stunden ab Deutschland (Lissabon)","timezone":"WEZ (UTC+0; im Sommer UTC+1), eine Stunde hinter MEZ (Festland)","visa":"Nicht erforderlich für EU-Bürger (Schengen-Raum)","bestMonths":"April bis Oktober"}$j$::jsonb, $j$["Lissabon – Alfama, die Straßenbahn 28, der Belém-Turm und Pastéis de Nata","Porto – die Ribeira, die Dom-Luís-Brücke und die Portweinkeller","Algarve – goldene Strände, Felsbuchten und die Benagil-Höhle","Sintra – die Märchenschlösser, allen voran der bunte Pena-Palast","Douro-Tal – terrassierte Weinberge und die Heimat des Portweins","Madeira und Azoren – üppige Natur auf den Atlantikinseln","Nazaré und Ericeira – berühmte Surfspots mit teils riesigen Wellen","Fado – die melancholische Musik in den Gassen von Lissabon und Coimbra"]$j$::jsonb, $j$["In Lissabon gehört eine Fahrt mit der historischen Straßenbahn 28 dazu; die original Pastéis de Belém isst man am besten frisch und noch lauwarm direkt beim namensgebenden Café.","Die spektakuläre Benagil-Höhle an der Algarve erreicht man per Boot, Kajak oder SUP – am ruhigsten ist es früh am Morgen.","Sintra lässt sich gut als Tagesausflug von Lissabon erleben; wegen des großen Andrangs sollte man früh kommen und Tickets für den Pena-Palast vorab buchen.","Für eine Portweinverkostung lohnt sich ein Besuch der Kellereien in Vila Nova de Gaia gegenüber von Porto; das Land erkundet man am flexibelsten per Mietwagen."]$j$::jsonb, $j$[{"question":"Wann ist die beste Reisezeit für Portugal?","answer":"Allgemein ist April bis Oktober ideal. Die Algarve und die Strände sind im Sommer am schönsten, während Frühling und Herbst angenehm mild und weniger voll sind – perfekt für Städtereisen, Wandern und Rundreisen."},{"question":"Welche Währung gilt in Portugal und brauche ich ein Visum?","answer":"In Portugal zahlt man mit dem Euro. Als EU- und Schengen-Mitglied ist kein Visum nötig; für die Einreise genügt ein gültiger Personalausweis oder Reisepass."},{"question":"Lohnt sich ein Mietwagen in Portugal?","answer":"Ja, für die Erkundung der Algarve, des Douro-Tals und ländlicher Regionen ist ein Mietwagen ideal. Lissabon und Porto erkundet man hingegen besser zu Fuß und mit dem guten Nahverkehr, da Parken in den Städten schwierig ist."},{"question":"Was sollte man in Lissabon und Porto sehen?","answer":"In Lissabon locken die Alfama, die Straßenbahn 28, der Belém-Turm und das Hieronymuskloster. In Porto sind die Ribeira am Fluss, die Dom-Luís-Brücke, der Bahnhof São Bento und die Portweinkeller in Gaia die Höhepunkte."},{"question":"Wie sind die Strände an der Algarve?","answer":"Die Algarve bietet einige der schönsten Strände Europas mit goldenem Sand, dramatischen Felsformationen und versteckten Buchten. Besonders bekannt sind Lagos, Praia da Marinha und die Benagil-Höhle. In der Hochsaison kann es voll werden."},{"question":"Kann man in Portugal surfen?","answer":"Ja, Portugals Atlantikküste ist ein Top-Surfrevier. Orte wie Ericeira, Peniche und die Algarve bieten Wellen für alle Niveaus, während Nazaré im Winter für seine gigantischen Wellen weltberühmt ist."},{"question":"Lohnen sich Madeira und die Azoren?","answer":"Ja, beide Atlantikinselgruppen sind eigene Reiseziele mit üppiger Natur. Madeira ist bekannt für Levada-Wanderungen und ganzjährig mildes Klima, die Azoren für vulkanische Landschaften, Kraterseen und Walbeobachtung."},{"question":"Spricht man in Portugal Englisch?","answer":"In Städten und touristischen Regionen wird häufig gut Englisch gesprochen, sodass die Verständigung meist unkompliziert ist. Ein paar portugiesische Höflichkeitsfloskeln werden jedoch sehr geschätzt."},{"question":"Ist Portugal für einen Familienurlaub geeignet?","answer":"Ja, Portugal ist familienfreundlich und sicher. Die Strände der Algarve, Bootstouren, Aquaparks, kinderfreundliche Städte und die Inseln bieten viel Abwechslung. Die Portugiesen gelten als ausgesprochen herzlich gegenüber Kindern."},{"question":"Wie viele Tage sollte man für Portugal einplanen?","answer":"Für eine Stadt wie Lissabon oder Porto reichen einige Tage. Wer Städte, die Algarve und vielleicht das Douro-Tal verbinden möchte, sollte 1 bis 2 Wochen einplanen."}]$j$::jsonb, $t$Portugal Urlaub: Lissabon, Algarve, Porto & beste Reisezeit$t$, $t$Dein Portugal-Urlaub: das charmante Lissabon, das Portwein-Porto, die Traumstrände der Algarve und die Schlösser von Sintra. Beste Reisezeit, Highlights, Roadtrip-Tipps und praktische Hinweise im Überblick.$t$, $t$Portugal Reise buchen, Flug nach Lissabon oder Porto, Mietwagen Portugal, Hotel Algarve, Städtereise Lissabon, Rundreise Portugal, Surfcamp Portugal$t$, true, $j$["spanien","italien","marokko"]$j$::jsonb, ARRAY[$t$Portugal$t$,$t$Lissabon$t$,$t$Alfama$t$,$t$Straßenbahn 28$t$,$t$Belém-Turm$t$,$t$Pastéis de Nata$t$,$t$Porto$t$,$t$Ribeira$t$,$t$Portwein$t$,$t$Algarve$t$,$t$Benagil-Höhle$t$,$t$Sintra$t$,$t$Pena-Palast$t$,$t$Douro-Tal$t$,$t$Madeira$t$,$t$Azoren$t$,$t$Fado$t$,$t$Nazaré$t$]::text[], $t$Portugal ist ein sonniges Land am Atlantik mit dem charmanten Lissabon samt Alfama und Straßenbahn 28, dem Portwein-Porto, den Traumstränden und Felsbuchten der Algarve, den Märchenschlössern von Sintra und den Atlantikinseln Madeira und Azoren. Bekannt für die melancholische Fado-Musik, exzellente Küche und meist moderate Preise, eignet es sich ideal für Strand-, Städte-, Roadtrip- und Genussreisen. Die beste Reisezeit liegt zwischen April und Oktober, im Landesinneren ist ein Mietwagen ideal.$t$, $t$Portugal begeistert mit Lissabon, dem Portwein-Porto, den Traumstränden der Algarve, den Schlössern von Sintra und Fado – ideal für Strand-, Städte- und Roadtrip-Reisen.$t$, $t$https://www.apearound.de/reiseziele/portugal$t$, $t$/images/destinations/portugal.jpg$t$, $t$/images/destinations/portugal.jpg$t$, $t$Portugal Urlaub: Lissabon, Algarve, Porto & beste Reisezeit$t$, $t$Dein Portugal-Urlaub: das charmante Lissabon, das Portwein-Porto, die Traumstrände der Algarve und die Schlösser von Sintra. Beste Reisezeit, Highlights, Roadtrip-Tipps und praktische Hinweise im Überblick.$t$, $t$Portugal Urlaub: Lissabon, Algarve, Porto & beste Reisezeit$t$, $t$Dein Portugal-Urlaub: das charmante Lissabon, das Portwein-Porto, die Traumstrände der Algarve und die Schlösser von Sintra. Beste Reisezeit, Highlights, Roadtrip-Tipps und praktische Hinweise im Überblick.$t$, $t$draft$t$)
